local config = {
  ui_story_5066_50660101_1_dialog_content = "Tangga, lemari, lantai...",
  ui_story_5066_50660101_2_dialog_content = "Fiuh... Akhirnya semuanya bersih.",
  ui_story_5066_50660101_3_dialog_content = "Itu berarti aku seharusnya sudah selesai dengan pembersihan hari ini... Benar?",
  ui_story_5066_50660101_4_dialog_content = "Connolly! Kemana kamu pergi? Apakah lantainya sudah bersih semua?",
  ui_story_5066_50660101_5_dialog_content = "Ah! Ini bibiku!",
  ui_story_5066_50660101_6_dialog_content = "A-Aku di ruang bawah tanah! Baru saja selesai di sini!",
  ui_story_5066_50660101_7_dialog_content = "Benarkah? Karena aku baru saja melihat beberapa noda di koridor lagi!",
  ui_story_5066_50660101_8_dialog_content = "Kita kedatangan tamu penting beberapa hari ini, dan seluruh keluarga sibuk. Jangan jadi beban!",
  ui_story_5066_50660101_9_dialog_content = "Oke... Aku akan segera ke sana!",
  ui_story_5066_50660101_10_dialog_content = "Ini seharusnya tempatnya...",
  ui_story_5066_50660101_11_dialog_content = "Ah! Seluruh area ini tertutup pasir dari sepatu orang-orang...",
  ui_story_5066_50660101_12_dialog_content = "Aku harus segera membersihkan ini dan langsung menuju loteng...",
  ui_story_5066_50660101_13_dialog_content = "Kalau tidak... Tante akan semakin tidak menyukai aku jika dia melihat ini.",
  ui_story_5066_50660101_14_dialog_content = "Hai, Connolly!",
  ui_story_5066_50660101_15_dialog_content = "Eek—Itu kamu, sepupu?",
  ui_story_5066_50660101_16_dialog_content = "T-Tapi kukira kamu dipromosikan ke posisi tinggi di bagian Dangkal...",
  ui_story_5066_50660101_17_dialog_content = "Haha, mengejutkan kamu masih ingat semua ini. Memang, sekarang aku menjadi anggota penting di Pengadilan Merman.",
  ui_story_5066_50660101_18_dialog_content = "Apakah kamu juga membersihkan ruang tamu hari ini? Hebat sekali, Connolly kecil!",
  ui_story_5066_50660101_19_dialog_content = "Aku akan selesai sebentar lagi... Aku tidak akan menyita waktu semua orang lagi!",
  ui_story_5066_50660101_20_dialog_content = "Kamu tidak akan menghadiri perjamuan keluarga?",
  ui_story_5066_50660101_21_dialog_content = "A-aku tak mungkin bisa menghadiri...",
  ui_story_5066_50660101_22_dialog_content = "Selama pesta... Bibi saya entah mengurung saya di loteng atau memaksa saya untuk meninggalkan rumah...",
  ui_story_5066_50660101_23_dialog_content = "Dia tidak ingin menakuti tamu-tamu kita, karena aku terlihat sangat aneh...",
  ui_story_5066_50660101_24_dialog_content = "Sayang sekali. Penampilanmu memang cukup aneh untuk seorang penduduk kota bawah laut ini.",
  ui_story_5066_50660101_25_dialog_content = "Namun, menurutku, keanehan ini merupakan bentuk estetika.",
  ui_story_5066_50660101_26_dialog_content = "Aku bisa mengenalkanmu pada pekerjaan yang lebih baik, di mana kamu tidak akan kesepian lagi.",
  ui_story_5066_50660101_27_dialog_content = "M-Maafkan aku, tapi aku harus pergi sekarang! Bibiku masih punya banyak hal yang harus aku lakukan!",
  ui_story_5066_50660101_28_dialog_content = "Hei, tahan sebentar!",
  ui_story_5066_50660101_29_dialog_content = "... Kurang penghargaan!",
  ui_story_5066_50660101_30_dialog_content = "Ah, syukurlah aku berhasil kabur...",
  ui_story_5066_50660101_31_dialog_content = "Dia tampak sangat tertarik padaku, tapi sikapnya yang menjijikkan benar-benar membuatku merasa tidak nyaman...",
  ui_story_5066_50660101_32_dialog_content = "Meskipun aku bisa pergi... Aku tidak akan pergi bersamanya...",
  ui_story_5066_50660101_33_dialog_content = "Aku tahu aku akan merasa kesepian jika pergi sendirian... Tapi aku benar-benar tidak keberatan untuk sendirian.",
  ui_story_5066_50660101_34_dialog_content = "Sejujurnya, berada di tempat tanpa orang lain sangat cocok untukku.",
  ui_story_5066_50660101_35_dialog_content = "<color=#e8d9bb>Connolly percaya bahwa jika tidak ada yang memperhatikannya, maka tidak ada yang bisa membencinya, menghindarinya, atau menudinginya.</color>",
  ui_story_5066_50660101_36_dialog_content = "Siapa itu? Penampilannya sangat aneh—sama sekali tidak mirip ikan. Apakah dia dari kota?",
  ui_story_5066_50660101_37_dialog_content = "Namanya Connolly, aku dengar. Dan dia anak angkat.",
  ui_story_5066_50660101_38_dialog_content = "Tidak tahu jenis ikan apa orang tuanya hingga punya anak yang aneh seperti ini.",
  ui_story_5066_50660101_39_dialog_content = "Aku satu-satunya yang terlihat berbeda di rumah ini...",
  ui_story_5066_50660101_40_dialog_content = "Mama dan Papa sudah pergi sekarang... Hanya tanteku yang bersedia merawatku...",
  ui_story_5066_50660101_41_dialog_content = "Tapi, betapa pun kerasnya aku berusaha menjadi bagian dari keluarga ini... Tidak ada tempat untukku di sini.",
  ui_story_5066_50660101_42_dialog_content = "Namun, aku tidak sepenuhnya merasa tidak bahagia...",
  ui_story_5066_50660101_43_dialog_content = "Dan itu karena... Saya masih punya musik saya! Saya masih memiliki instrumen dan kertas musik yang ditinggalkan mama saya...",
  ui_story_5066_50660101_44_dialog_content = "<color=#e8d9bb>Setiap kali Connolly merasa kesepian, dia memainkan melodi-melodi yang akrab.</color>",
  ui_story_5066_50660101_45_dialog_content = "<color=#e8d9bb>Mars gembira dalam A Major, balada lirik dalam B Minor, dan sonata muram dalam C Major. Lagu-lagu ini bukan hanya teman-temannya, tetapi juga penyelamatnya.</color>",
  ui_story_5066_50660101_46_dialog_content = "Sekarang lagu apa yang harus kumainkan hari ini...?",
  ui_story_5066_50660101_47_dialog_content = "Hah...? Skor ini...",
  ui_story_5066_50660101_48_dialog_content = "K-K-Kenapa musik menyeramkan ini masih ada di sini?!",
  ui_story_5066_50660101_49_dialog_content = "Terakhir kali aku memainkannya, sesuatu yang sangat mengerikan terjadi!",
  ui_story_5066_50660101_50_dialog_content = "Bahkan makhluk itu memanggil monster bertentakel, yang menyebut dirinya sendiri...",
  ui_story_5066_50660101_51_dialog_content = "Saya adalah <color=#FFB400>Aqua Lord</color>...",
  ui_story_5066_50660101_52_dialog_content = "Yang tersegel... kuno... Aqua Lord!",
  ui_story_5066_50660101_53_dialog_content = "Putri biasa dari air yang memegang relik suci, apakah kamu dapat memahami kata-kataku?",
  ui_story_5066_50660101_54_dialog_content = "…?",
  ui_story_5066_50660101_55_dialog_content = "Aaaaaaaah! I-Ini monster!",
  ui_story_5066_50660101_56_dialog_content = "Tolong jangan makan aku!!!",
  ui_story_5066_50660101_57_dialog_content = "... Saya tidak pernah mengonsumsi makhluk fana!",
  ui_story_5066_50660101_58_dialog_content = "Aku di sini karena klarinetmu bukanlah hal yang biasa...",
  ui_story_5066_50660101_59_dialog_content = "Musikmu membawa saya ke sini.",
  ui_story_5066_50660101_60_dialog_content = "Aku ingin membentuk perjanjian denganmu.",
  ui_story_5066_50660101_61_dialog_content = "Sebuah... pakta?",
  ui_story_5066_50660101_62_dialog_content = "Ya, Aqua Pact yang perkasa! Dengan Pact, kamu bisa menjadi ratu dan menguasai seluruh dunia bawah laut!",
  ui_story_5066_50660101_63_dialog_content = "Ratu... dari dunia bawah laut...",
  ui_story_5066_50660101_64_dialog_content = "Lalu, yang perlu kamu lakukan hanyalah memainkan peninggalan suci yang melambangkan perjanjian kita... klarinet ini!",
  ui_story_5066_50660101_65_dialog_content = "Kekuatan saya akan terwujud, membantu Anda menaklukkan semua lautan!",
  ui_story_5066_50660101_66_dialog_content = "Kamu tidak perlu takut pada apapun di dunia ini lagi!",
  ui_story_5066_50660101_67_dialog_content = "Sekarang, katakan, apa jawabanmu?",
  ui_story_5066_50660101_68_dialog_content = "... May Bolehkah saya menolak, tolong?",
  ui_story_5066_50660101_69_dialog_content = "?",
  ui_story_5066_50660101_70_dialog_content = "Ah! Uh, k-kamu tahu... Tentang menjadi ratu dan segala macamnya...",
  ui_story_5066_50660101_71_dialog_content = "Kurasa aku tak bisa melakukan sesuatu yang terdengar begitu sulit atau mencolok...",
  ui_story_5066_50660101_72_dialog_content = "K-Keinginan terbesarku adalah agar orang-orang berhenti memperhatikanku...",
  ui_story_5066_50660101_73_dialog_content = "Aku tidak ingin ada masalah. Aku hanya ingin mendengarkan musikku...",
  ui_story_5066_50660101_74_dialog_content = "<size=33>Jika aku punya satu atau dua teman, atau mungkin tiga untuk mendengarkan musik bersamaku... Itu sudah cukup...</size>",
  ui_story_5066_50660101_75_dialog_content = "...",
  ui_story_5066_50660101_76_dialog_content = "Aku mengerti. Kamu belum siap untuk menanggung tanggung jawab dari dunia bawah air.",
  ui_story_5066_50660101_77_dialog_content = "Tapi kertas musik ini adalah bukti dari potensi perjanjian kita.",
  ui_story_5066_50660101_78_dialog_content = "Untuk memanggilku, mainkanlah dengan klarinetmu.",
  ui_story_5066_50660101_79_dialog_content = "Coba mainkan... mainkan... mainkan...",
  ui_story_5066_50660101_80_dialog_content = "Kupikir ini hanya instrumen berharga mama yang ditinggalkan untukku...",
  ui_story_5066_50660101_81_dialog_content = "Mengapa ia bisa memanggil makhluk misterius seperti itu...?",
  ui_story_5066_50660101_82_dialog_content = "Ini tidak akan tinggal bersamaku selamanya... Bukan?",
  ui_story_5066_50660101_83_dialog_content = "Mainkan itu...",
  ui_story_5066_50660101_84_dialog_content = "Pakta itu...",
  ui_story_5066_50660101_85_dialog_content = "Untuk memanggilku...",
  ui_story_5066_50660101_86_dialog_content = "Ahhhhh... Hanya memikirkannya membuatku mendengar suara itu lagi!",
  ui_story_5066_50660101_87_dialog_content = "Aku hanya perlu... fokus pada hal lain...",
  ui_story_5066_50660101_88_dialog_content = "<color=#e8d9bb>Ketuk, ketuk, ketuk—</color>",
  ui_story_5066_50660101_89_dialog_content = "Hah? Siapa yang mencari saya di loteng pada jam segini...?",
  ui_story_5066_50660101_90_dialog_content = "Connolly! Bahan-bahan dapur kita mulai menipis lagi! Cepat pergi beli beberapa!",
  ui_story_5066_50660101_91_dialog_content = "Oh... Oke! Aku akan pergi sekarang!",
  ui_story_5066_50660201_1_dialog_content = "Fiuh... Ini seharusnya bisa mencegah bibiku terlalu marah.",
  ui_story_5066_50660201_2_dialog_content = "Tapi, apa yang terjadi hari ini...?",
  ui_story_5066_50660201_3_dialog_content = "Sudah waktunya belum? Kenapa mereka belum datang?",
  ui_story_5066_50660201_4_dialog_content = "Permisi, maafkan saya...",
  ui_story_5066_50660201_5_dialog_content = "Huhu... Kenapa jalanan begitu ramai hari ini?",
  ui_story_5066_50660201_6_dialog_content = "Sepertinya semua orang keluar untuk melihat sesuatu... Apakah hari ini ada liburan spesial...?",
  ui_story_5066_50660201_7_dialog_content = "Apa katamu?",
  ui_story_5066_50660201_8_dialog_content = "Maksud kamu tidak tahu? Hari ini adalah hari <color=#FFB400>putra mahkota</color> keluar! Semua orang berada di jalanan, berusaha melihat sekilas putra mahkota!",
  ui_story_5066_50660201_9_dialog_content = "Hah, aku ingin melihat wajah orang yang selalu memungut pajak dari kita semua!",
  ui_story_5066_50660201_10_dialog_content = "... Saya tidak menyangka akan menghadapi ini hari ini. Kerumunan seperti ini sangat menakutkan bagi saya.",
  ui_story_5066_50660201_11_dialog_content = "Aku harus segera kembali setelah selesai membeli persediaan...",
  ui_story_5066_50660201_12_dialog_content = "Itu pangeran! Pangeran ada di sini!",
  ui_story_5066_50660201_13_dialog_content = "Ha.",
  ui_story_5066_50660201_14_dialog_content = "Aduh, ini benar-benar membosankan, sangat, sangat membosankan!",
  ui_story_5066_50660201_15_dialog_content = "Kota yang buruk. Lebih baik aku tinggal di dalam dan tidak pernah keluar. Kenapa ayahku memberikan tempat kumuh yang bobrok ini padaku?",
  ui_story_5066_50660201_16_dialog_content = "Yang Mulia, harap tenang.",
  ui_story_5066_50660201_17_dialog_content = "Lagi pula, ini juga wilayahmu, dan semua orang ingin bertemu denganmu.",
  ui_story_5066_50660201_18_dialog_content = "Maka mereka harus membayar pajak lebih banyak... Tunggu sebentar!",
  ui_story_5066_50660201_19_dialog_content = "Lihat gadis ini! Dia benar-benar satu-satunya...",
  ui_story_5066_50660201_20_dialog_content = "Serius, apakah benar ada ikan dengan penampilan yang aneh seperti itu?",
  ui_story_5066_50660201_21_dialog_content = "Dia mungkin terlihat sedikit aneh, tapi sebagai koleksi, dia mungkin sangat berharga.",
  ui_story_5066_50660201_22_dialog_content = "<size=33>Tsk, apa yang Connolly lakukan di sini... Bukankah dia seharusnya ada di loteng?</size>",
  ui_story_5066_50660201_23_dialog_content = "<size=33>Tapi saya tidak menyangka sang pangeran tertarik padanya; ini mungkin kesempatan langka...</size>",
  ui_story_5066_50660201_24_dialog_content = "Yang Mulia, agak memalukan untuk mengakuinya, tapi gadis ini sebenarnya adalah saudariku.",
  ui_story_5066_50660201_25_dialog_content = "Dia hampir menjadi kutukan di rumah. Tapi jika bicara tentang penampilan unik, tidak ada yang bisa mengalahkannya.",
  ui_story_5066_50660201_26_dialog_content = "Kalau kamu tertarik, aku bisa menjual... menawarkannya kepadamu sekarang juga.",
  ui_story_5066_50660201_27_dialog_content = "Oh, itu agak kebetulan. Kamu perhatian sekali.",
  ui_story_5066_50660201_28_dialog_content = "Tapi pertama, aku akan melihat lebih dekat untuk mencari tahu apa masalahnya dengan dia.",
  ui_story_5066_50660201_29_dialog_content = "Sudah saatnya aku bersenang-senang mengunjungi kota yang jelek ini. Harus memanfaatkan sebaik mungkin.",
  ui_story_5066_50660201_30_dialog_content = "Kesini, Yang Mulia. Jika Anda memerlukan bantuan, jangan ragu untuk memberikan perintah Anda.",
  ui_story_5066_50660201_31_dialog_content = "Kru pangeran sedang bergerak!",
  ui_story_5066_50660201_32_dialog_content = "Ke mana dia pergi? Ayo, ikuti saja dan lihat ada apa!",
  ui_story_5066_50660201_33_dialog_content = "Ah—Kerumunan mulai bergerak lagi!",
  ui_story_5066_50660201_34_dialog_content = "T-T-Tunggu! Aku terdorong keluar...",
  ui_story_5066_50660201_35_dialog_content = "Aduh!",
  ui_story_5066_50660201_36_dialog_content = "...",
  ui_story_5066_50660201_37_dialog_content = "Siapa gadis ini? Berani sekali menghadang jalan sang pangeran.",
  ui_story_5066_50660201_38_dialog_content = "Wow, dia terlihat sangat aneh; sama sekali tidak terlihat seperti ikan!",
  ui_story_5066_50660201_39_dialog_content = "Aduh! Oh tidak... Tolong bilang pakaianku tidak kotor! Aku memang tidak punya banyak pakaian...",
  ui_story_5066_50660201_40_dialog_content = "Kenapa rasanya semua orang menatapku...?",
  ui_story_5066_50660201_41_dialog_content = "Hei, kamu di sana! Berhenti melihat sekeliling—maksudku kamu!",
  ui_story_5066_50660201_42_dialog_content = "Eek!",
  ui_story_5066_50660201_43_dialog_content = "Penampilanmu yang cukup jelek menarik perhatianku.",
  ui_story_5066_50660201_44_dialog_content = "Ini undangan untuk kamu—untuk menjadi bagian berharga dalam koleksiku!",
  ui_story_5066_50660201_45_dialog_content = "Percayalah padaku, hidup bersamaku di perairan dangkal jauh lebih baik daripada terjebak di kota yang menyedihkan ini.",
  ui_story_5066_50660201_46_dialog_content = "Kamu tahu maksudku, kan?",
  ui_story_5066_50660201_47_dialog_content = "Um... B-May bolehkah aku menolak?",
  ui_story_5066_50660201_48_dialog_content = "Connolly, jangan sia-siakan niat baikku!",
  ui_story_5066_50660201_49_dialog_content = "Aku benar-benar sudah memuji-muji kamu di depan pangeran agar kamu bisa mendapatkan kesempatan ini!",
  ui_story_5066_50660201_50_dialog_content = "Ini kah pekerjaan baru yang kamu ceritakan padaku...?",
  ui_story_5066_50660201_51_dialog_content = "Kamu ingin... <size=45>menjualku kepada pangeran?!</size>",
  ui_story_5066_50660201_52_dialog_content = "Jangan dibuat terdengar buruk. Ini bukan menjual; ini menjadikanmu teman kerajaan yang terhormat...",
  ui_story_5066_50660201_53_dialog_content = "Sebagai sepupumu, aku sudah menemukan jalan terbaik untukmu.",
  ui_story_5066_50660201_54_dialog_content = "Kalau tidak, kau akan terjebak di rumah terus menerus melakukan pekerjaan pelayan. Apa kau tidak merasa kesepian?",
  ui_story_5066_50660201_55_dialog_content = "Kesepian...? Aku sudah bilang sebelumnya, aku tidak merasa kesepian. Yang kubutuhkan hanyalah musik dan klarinetku!",
  ui_story_5066_50660201_56_dialog_content = "Klarinet? Apakah itu instrumen aneh yang ada di tanganmu?",
  ui_story_5066_50660201_57_dialog_content = "Wow, sepertinya ini artifak kuno... cukup tidak biasa.",
  ui_story_5066_50660201_58_dialog_content = "Berikan padaku untuk melihat lebih dekat.",
  ui_story_5066_50660201_59_dialog_content = "Ah! Aku... Aku tidak bisa membiarkanmu!",
  ui_story_5066_50660201_60_dialog_content = "Tak ada yang bisa menolakku di bawah laut! Serahkan itu!",
  ui_story_5066_50660201_61_dialog_content = "Tapi... Tapi ibuku yang meninggalkannya untukku...",
  ui_story_5066_50660201_62_dialog_content = "Ibu? Ngomong-ngomong, dengan penampilan unikmu, aku cukup penasaran seperti apa ibumu.",
  ui_story_5066_50660201_63_dialog_content = "Jika memungkinkan, akan sangat keren jika kalian berdua bisa menjadi koleksi saya bersama-sama.",
  ui_story_5066_50660201_64_dialog_content = "…?",
  ui_story_5066_50660201_65_dialog_content = "Tolong jangan lihat saya, Yang Mulia. Dia anak angkat; ibunya bukan ibu saya...",
  ui_story_5066_50660201_66_dialog_content = "Tidak...",
  ui_story_5066_50660201_67_dialog_content = "Apa?!",
  ui_story_5066_50660201_68_dialog_content = "Aku tak akan membiarkan kamu menghina Mama seperti itu!",
  ui_story_5066_50660201_69_dialog_content = "Konyol!",
  ui_story_5066_50660201_70_dialog_content = "Di bawah laut di sini, tidak ada yang berani berbicara padaku seperti itu.",
  ui_story_5066_50660201_71_dialog_content = "Karena kamu tidak mau menyerahkannya... jangan salahkan aku jika bersikap kasar!",
  ui_story_5066_50660201_72_dialog_content = "<color=#e8d9bb>Pangeran melompat menuju Connolly.</color>",
  ui_story_5066_50660201_73_dialog_content = "Tidak... Menjauh dariku...!",
  ui_story_5066_50660201_74_dialog_content = "<color=#e8d9bb><size=45>Plak—</size></color>",
  ui_story_5066_50660201_75_dialog_content = "<size=45>Aduh!!!</size>",
  ui_story_5066_50660201_76_dialog_content = "…?!",
  ui_story_5066_50660201_77_dialog_content = "...!!!",
  ui_story_5066_50660201_78_dialog_content = "Bagaimana... beraninya kau menyerangku dengan senjata?!",
  ui_story_5066_50660201_79_dialog_content = "Ah... A-Aku sangat minta maaf, aku tidak bermaksud melakukan itu...",
  ui_story_5066_50660201_80_dialog_content = "T-Tapi meskipun begitu... <size=30>Ini adalah salahmu sendiri...</size>",
  ui_story_5066_50660201_81_dialog_content = "Apa yang kamu katakan?... Penjaga! Di mana para penjaga?!",
  ui_story_5066_50660201_82_dialog_content = "Tangkap gadis yang berani dan cacat bentuk itu untukku!",
  ui_story_5066_50660201_83_dialog_content = "Ya!!!",
  ui_story_5066_50660201_84_dialog_content = "Aaah... Connolly, kamu pembuat masalah! Kita kacau...",
  ui_story_5066_50660201_85_dialog_content = "Oh tidak... A-Aku rasa aku benar-benar dalam masalah besar sekarang...",
  ui_story_5066_50660201_86_dialog_content = "Aku selesai jika mereka menangkapku, tidak diragukan lagi... Aku harus kabur! Tidak ada pilihan lain untukku!",
  ui_story_5066_50660201_87_dialog_content = "Maafkan saya... Tolong biarkan saya lewat!",
  ui_story_5066_50660201_88_dialog_content = "<color=#e8d9bb>Dia ingin menghindari kerumunan, bersembunyi di tempat di mana tak ada yang bisa menemukannya.</color>",
  ui_story_5066_50660201_89_dialog_content = "<color=#e8d9bb>Tapi apakah itu mungkin di jalan bawah laut yang ramai seperti ini...?</color>",
  ui_story_5066_50660302_1_dialog_content = "Aduh... Berdiri menjaga adalah pekerjaan paling membosankan di dunia!",
  ui_story_5066_50660302_2_dialog_content = "Benarkah tidak ada orang jahat di sekitar sini? Aku tidak keberatan adu jotos sekarang juga.",
  ui_story_5066_50660302_3_dialog_content = "Dibandingkan bertarung... Aku lebih suka jika kita bisa bersama dalam damai...",
  ui_story_5066_50660302_4_dialog_content = "Ya, aku tahu. Aku tidak serius, aku hanya meluapkan kekesalan.",
  ui_story_5066_50660302_5_dialog_content = "Baiklah…",
  ui_story_5066_50660302_6_dialog_content = "Meskipun saya tidak keberatan jika Connolly datang untuk mengobrol sebentar juga!",
  ui_story_5066_50660302_7_dialog_content = "Kita sudah lama nggak melihatnya, ya?",
  ui_story_5066_50660302_8_dialog_content = "Kudengar... Keluarganya sedang menunggu tamu penting... Mungkin dia sibuk mengurus rumah.",
  ui_story_5066_50660302_9_dialog_content = "Merawat rumah?",
  ui_story_5066_50660302_10_dialog_content = "Ugh, jika selama ini dia terkurung di rumah, pasti bibi yang menyebalkan itu membuat hidupnya menjadi sengsara.",
  ui_story_5066_50660302_11_dialog_content = "Jika suatu saat nanti aku punya kesempatan, aku benar-benar ingin menamparnya satu atau dua kali untuk Connolly!",
  ui_story_5066_50660302_12_dialog_content = "Aku... tidak akan menghentikanmu melakukan itu.",
  ui_story_5066_50660302_13_dialog_content = "Connolly telah membantu kita dengan urusan kita selama ini, tetapi kita belum memiliki kesempatan untuk membalasnya... Hal itu benar-benar mulai mengganggu pikiran saya...",
  ui_story_5066_50660302_14_dialog_content = "Iya, 'kan?",
  ui_story_5066_50660302_15_dialog_content = "Dia juga tidak mau menerima uang untuk itu. Bahkan, dia bilang dia berterima kasih kepada kita...",
  ui_story_5066_50660302_16_dialog_content = "Oh... Aku benar-benar tidak butuh uang untuk menjalankan urusan untukmu...",
  ui_story_5066_50660302_17_dialog_content = "Aku... Aku hanya senang bisa keluar rumah sesekali...",
  ui_story_5066_50660302_18_dialog_content = "Bagaimanapun juga... Bibiku sering memarahiku setiap kali aku berada di rumah...",
  ui_story_5066_50660302_19_dialog_content = "Jadi, tolong... tolong panggil aku jika ada tugas yang perlu aku lakukan!",
  ui_story_5066_50660302_20_dialog_content = "Dia memang gadis yang baik, ya.",
  ui_story_5066_50660302_21_dialog_content = "Dia sama sekali tidak seperti penyihir serakah dan licik yang dulu kita kerjakan!",
  ui_story_5066_50660302_22_dialog_content = "<size=45>Ohhhhhh!</size>",
  ui_story_5066_50660302_23_dialog_content = "Apa ini kebisingannya? Ada sesuatu yang terjadi di sana?",
  ui_story_5066_50660302_24_dialog_content = "Ya... Dan sepertinya cukup ramai juga.",
  ui_story_5066_50660302_25_dialog_content = "Aku benar-benar ingin pergi melihat! Berapa lama lagi kita harus berdiri dan menjaga?!",
  ui_story_5066_50660302_26_dialog_content = "Aku tahu perasaanmu... Tapi ini masih sangat awal di shift kita...",
  ui_story_5066_50660302_27_dialog_content = "Lagi pula, keributan seperti ini cukup umum.",
  ui_story_5066_50660302_28_dialog_content = "Dengan adanya raja yang sombong dan pangeran yang angkuh, penghuni laut mengalami masa-masa yang sulit.",
  ui_story_5066_50660302_29_dialog_content = "Bisakah itu karena pangeran bodoh itu diserang oleh penduduk yang marah? Nah, itu pasti menarik.",
  ui_story_5066_50660302_30_dialog_content = "Kalau sesuatu seperti itu benar-benar terjadi di depan mataku...",
  ui_story_5066_50660302_31_dialog_content = "Aku akan berpura-pura tidak melihat apa-apa...",
  ui_story_5066_50660302_32_dialog_content = "Di sini!",
  ui_story_5066_50660302_33_dialog_content = "Hei, kalian berdua!",
  ui_story_5066_50660302_34_dialog_content = "Pengawal sang pangeran?",
  ui_story_5066_50660302_35_dialog_content = "Jangan bilang aku benar...",
  ui_story_5066_50660302_36_dialog_content = "Kamu pernah melihat seorang gadis yang tampak aneh berlari ke arah ini, seseorang yang membawa klarinet?",
  ui_story_5066_50660302_37_dialog_content = "...",
  ui_story_5066_50660302_38_dialog_content = "(Ini Connolly...)",
  ui_story_5066_50660302_39_dialog_content = "(Apa yang diinginkan pangeran darinya?)",
  ui_story_5066_50660302_40_dialog_content = "(Apa pun yang dia rencanakan, kita tidak bisa membiarkannya berhasil.)",
  ui_story_5066_50660302_41_dialog_content = "Tidak apa-apa, saya tidak berharap kalian melihatnya. Kalian berdua adalah anggota tim pencarian sekarang! Mulailah mencari dari sini!",
  ui_story_5066_50660302_42_dialog_content = "Uh... May kita tanya apa yang baru saja terjadi...?",
  ui_story_5066_50660302_43_dialog_content = "Apa yang terjadi? Heh, gadis yang tampak aneh itu benar-benar berani menyerang pangeran!",
  ui_story_5066_50660302_44_dialog_content = "Ini belum pernah terjadi sebelumnya!",
  ui_story_5066_50660302_45_dialog_content = "Dia akan menyesal begitu aku menangkapnya!",
  ui_story_5066_50660302_46_dialog_content = "<size=33>Baik, Connolly! Bagus!</size>",
  ui_story_5066_50660302_47_dialog_content = "Apa katamu barusan?",
  ui_story_5066_50660302_48_dialog_content = "Oh tidak apa-apa, hanya saja kami akan melakukan pekerjaan kami sebaik mungkin.",
  ui_story_5066_50660302_49_dialog_content = "Nah, angkat pantatmu dan ayo bergerak!",
  ui_story_5066_50660302_50_dialog_content = "Siap, Pak!",
  ui_story_5066_50660302_51_dialog_content = "...",
  ui_story_5066_50660302_52_dialog_content = "Oh, tidak, Connolly dalam bahaya serius kali ini.",
  ui_story_5066_50660302_53_dialog_content = "Kamu benar... Kita harus segera menemukannya...",
  ui_story_5066_50660302_54_dialog_content = "Dan kita harus menemukannya sebelum para pengawal ini melakukannya, jika tidak, keadaan akan semakin buruk.",
  ui_story_5066_50660401_1_dialog_content = "Heh, heh...",
  ui_story_5066_50660401_2_dialog_content = "Saya rasa... saya kehilangan mereka...",
  ui_story_5066_50660401_3_dialog_content = "Kepala ke sini! Cari!",
  ui_story_5066_50660401_4_dialog_content = "Ah... Oh, tidak...",
  ui_story_5066_50660401_5_dialog_content = "Jika aku menggulung diri dan bersembunyi di sini... Mereka seharusnya tidak bisa menemukanku...",
  ui_story_5066_50660401_6_dialog_content = "Jantungku... Berdebar sangat cepat... Aku merasa tidak bisa bernapas...",
  ui_story_5066_50660401_7_dialog_content = "Ke sini! Di sini!",
  ui_story_5066_50660401_8_dialog_content = "Ahhh... Tolong jangan temukan aku, tolong jangan temukan aku, tolong jangan temukan aku...",
  ui_story_5066_50660401_9_dialog_content = "Kamu tidak perlu lari, bukan?",
  ui_story_5066_50660401_10_dialog_content = "…?!",
  ui_story_5066_50660401_11_dialog_content = "Buat perjanjian dengan saya, dan semua masalah akan hilang.",
  ui_story_5066_50660401_12_dialog_content = "Kamu, saatnya untuk membuat pilihan...",
  ui_story_5066_50660401_13_dialog_content = "T-tapi...",
  ui_story_5066_50660401_14_dialog_content = "Situasi sudah seperti ini; apa yang perlu diragukan?",
  ui_story_5066_50660401_15_dialog_content = "A-Aku tahu... Tapi...",
  ui_story_5066_50660401_16_dialog_content = "<size=33>Ide tentang... terlibat dengan makhluk aneh seperti itu...</size>",
  ui_story_5066_50660401_17_dialog_content = "<size=33>Kedengarannya juga tidak begitu menyenangkan...</size>",
  ui_story_5066_50660401_18_dialog_content = "Keras dan jelas, aku mendengar kata-katamu.",
  ui_story_5066_50660401_19_dialog_content = "Ah... Maaf! Aku... Aku tidak bermaksud seperti itu...",
  ui_story_5066_50660401_20_dialog_content = "Pengawal pergi ke sana! Mari kita periksa di sini!",
  ui_story_5066_50660401_21_dialog_content = "Benar. Aku bisa merasakannya... Dia di dekat sini...",
  ui_story_5066_50660401_22_dialog_content = "...",
  ui_story_5066_50660401_23_dialog_content = "Aduh, aku menghabiskan terlalu banyak waktu ngobrol dengan suara itu...",
  ui_story_5066_50660401_24_dialog_content = "Aku benar-benar lupa tentang bahaya di sekitar ku...",
  ui_story_5066_50660401_25_dialog_content = "Sniff... A-Apa aku benar-benar harus menjadi bagian dari koleksi sang pangeran...?",
  ui_story_5066_50660401_26_dialog_content = "Ini dia Connolly! Akhirnya kita menemukannya!",
  ui_story_5066_50660401_27_dialog_content = "Fiuh... Syukurlah... Kita sampai padanya sebelum orang-orang itu...",
  ui_story_5066_50660401_28_dialog_content = "Hah…?",
  ui_story_5066_50660401_29_dialog_content = "Kamu baik-baik saja, Connolly? Mereka tidak menyakitimu, kan?",
  ui_story_5066_50660401_30_dialog_content = "I-Ini kamu, Dayna... Dan Robyn juga?",
  ui_story_5066_50660401_31_dialog_content = "... *mengangguk*",
  ui_story_5066_50660401_32_dialog_content = "Oh, senang sekali bertemu kalian berdua! Tapi maaf... Aku benar-benar tidak punya waktu untuk membantu urusan kalian hari ini...",
  ui_story_5066_50660401_33_dialog_content = "Sekarang bukan waktunya untuk itu, Connolly.",
  ui_story_5066_50660401_34_dialog_content = "Kita harus keluar dari sini sebelum pengawal pangeran menemukan kamu!",
  ui_story_5066_50660401_35_dialog_content = "Bagaimana kamu tahu tentang pangeran? Oh tidak... Jangan bilang tempat ini juga tidak aman?",
  ui_story_5066_50660401_36_dialog_content = "Kalau mereka menemukanku di sini... B-Bagaimana ini...?",
  ui_story_5066_50660401_37_dialog_content = "Jangan khawatir... Dayna punya ide yang bagus...",
  ui_story_5066_50660401_38_dialog_content = "B... Benarkah?",
  ui_story_5066_50660401_39_dialog_content = "Yap! Kita akan menunggu para penjaga itu muncul, lalu berikan mereka informasi yang salah dan arahkan mereka mencari di tempat lain.",
  ui_story_5066_50660401_40_dialog_content = "Itu harus memberimu cukup waktu untuk mencari tempat aman untuk bersembunyi.",
  ui_story_5066_50660401_41_dialog_content = "Ah... Terima kasih banyak, tapi... Aku tidak tahu bagaimana cara membalas kebaikan kalian berdua...",
  ui_story_5066_50660401_42_dialog_content = "Tch, tidak ada gunanya mengatakan itu, bukan?",
  ui_story_5066_50660401_43_dialog_content = "Kamu telah membantu kami dalam waktu yang lama... Kami lah yang belum membalas bantuanmu...",
  ui_story_5066_50660401_44_dialog_content = "Namun…",
  ui_story_5066_50660401_45_dialog_content = "Baiklah baiklah, simpan saja untuk lain waktu. Anda akan kehilangan kesempatan jika tidak segera bergerak.",
  ui_story_5066_50660401_46_dialog_content = "Sekarang pergi... Dan jangan menoleh ke belakang...",
  ui_story_5066_50660401_47_dialog_content = "Ba-baik!",
  ui_story_5066_50660401_48_dialog_content = "Ayo cepat, kalian yang tak berguna! Kenapa masih berlama-lama di sini?",
  ui_story_5066_50660401_49_dialog_content = "Intel mengatakan dia ada di gang ini, 'kan? Kalau salah, kamu yang akan menanggung akibatnya!",
  ui_story_5066_50660401_50_dialog_content = "Heh, sepertinya kita terlambat.",
  ui_story_5066_50660401_51_dialog_content = "Jadi... Apa yang harus kita lakukan, Dayna?",
  ui_story_5066_50660401_52_dialog_content = "Kita harus memblokir pintu masuk ke gang itu, agar Connolly memiliki cukup waktu untuk melarikan diri.",
  ui_story_5066_50660401_53_dialog_content = "Tidak peduli apa, kita tidak bisa membiarkan mereka mengendalikan dia.",
  ui_story_5066_50660401_54_dialog_content = "Benar.",
  ui_story_5066_50660401_55_dialog_content = "Um... J-Tunggu sebentar ya...",
  ui_story_5066_50660401_56_dialog_content = "Aku... Aku sangat berterima kasih atas bantuanmu... Sungguh...",
  ui_story_5066_50660401_57_dialog_content = "Tapi kamu... Kamu benar-benar tidak perlu pergi sejauh itu... untuk seseorang sepertiku...",
  ui_story_5066_50660401_58_dialog_content = "Aku tidak... ingin merepotkan kalian berdua...",
  ui_story_5066_50660401_59_dialog_content = "Jangan membuat kami terdengar seperti orang asing, Connolly! Kau akan melukai perasaan kami!",
  ui_story_5066_50660401_60_dialog_content = "Sebenarnya... Kami sudah lama... ingin membalas kebaikanmu...",
  ui_story_5066_50660401_61_dialog_content = "Yup, tapi kamu tidak membuatnya mudah untuk kami, karena kamu selalu bersembunyi dari semua orang.",
  ui_story_5066_50660401_62_dialog_content = "Terkadang aku khawatir bibimu mengurungmu, dan itu membuatku ingin pergi menyelamatkanmu.",
  ui_story_5066_50660401_63_dialog_content = "Jadi tolong... Mari kami membantu kamu kali ini...",
  ui_story_5066_50660401_64_dialog_content = "Saya akan ke kiri dan kamu ke kanan. Ayo, Robyn.",
  ui_story_5066_50660401_65_dialog_content = "Oke, Dayna.",
  ui_story_5066_50660402_1_dialog_content = "Apakah aku... Apakah aku berhasil kabur...?",
  ui_story_5066_50660402_2_dialog_content = "Terima kasih, Dayna dan Robyn...",
  ui_story_5066_50660402_3_dialog_content = "...",
  ui_story_5066_50660402_4_dialog_content = "Demi mereka, aku... aku tidak boleh sampai tertangkap!",
  ui_story_5066_50660402_5_dialog_content = "*terkesiap* Aku... Aku rasa aku harus aman di sini...",
  ui_story_5066_50660402_6_dialog_content = "...",
  ui_story_5066_50660402_7_dialog_content = "Ah...",
  ui_story_5066_50660402_8_dialog_content = "Seorang penjaga yang lewat? Sepertinya... dia tidak menyadari keberadaanku...",
  ui_story_5066_50660402_9_dialog_content = "Tetapi... Raja dan pangeran mengendalikan seluruh area ini... Di mana aku bisa bersembunyi di sekitar sini?",
  ui_story_5066_50660402_10_dialog_content = "Sebanyak apapun aku tak tahan... Aku bahkan tidak bisa kembali ke loteng di rumah bibiku...",
  ui_story_5066_50660402_11_dialog_content = "Sepupuku akan menemukan cara untuk memperkenalkan aku kepada pangeran...",
  ui_story_5066_50660402_12_dialog_content = "...",
  ui_story_5066_50660402_13_dialog_content = "Aku tidak cukup kuat untuk melawan mereka semua sendirian...",
  ui_story_5066_50660402_14_dialog_content = "Yang berarti... Aku hanya punya satu pilihan yang tersisa, bukan...?",
  ui_story_5066_50660402_15_dialog_content = "Untuk memanggilku, mainkanlah dengan klarinetmu.",
  ui_story_5066_50660402_16_dialog_content = "Aku benar-benar akan memainkannya... Aku masih sangat gugup...",
  ui_story_5066_50660402_17_dialog_content = "Tapi setelah semua ini, Mama memang meninggalkanku dengan klarinet ini...",
  ui_story_5066_50660402_18_dialog_content = "Aku harus... berani...",
  ui_story_5066_50660402_19_dialog_content = "*memainkan klarinet*",
  ui_story_5066_50660402_20_dialog_content = "...",
  ui_story_5066_50660402_21_dialog_content = "Saya senang melihat Anda akhirnya mengambil keputusan...",
  ui_story_5066_50660402_22_dialog_content = "Ayo, buat perjanjian dengan saya sekarang!",
  ui_story_5066_50660402_23_dialog_content = "B-Bisakah aku minta porsi kedua...?",
  ui_story_5066_50660402_24_dialog_content = "Pada titik ini, kamu tidak bisa kembali lagi.",
  ui_story_5066_50660402_25_dialog_content = "Aku... Aku tidak akan menyesal, tapi... Aku hanya ingin memastikan sesuatu dulu.",
  ui_story_5066_50660402_26_dialog_content = "Kamu tidak... akan menyuruhku melakukan hal yang mengerikan, 'kan?",
  ui_story_5066_50660402_27_dialog_content = "Tujuan utamaku adalah agar kamu menjadi ratu, yang memerintah seluruh kerajaan bawah laut.",
  ui_story_5066_50660402_28_dialog_content = "Mengerikan atau tidak, semuanya terserah pilihanmu sendiri.",
  ui_story_5066_50660402_29_dialog_content = "Tapi... Jika aku menjadi ratu atau apapun itu... Bukankah aku akan terlalu mencolok?",
  ui_story_5066_50660402_30_dialog_content = "Aku hanya... tidak ingin melakukan sesuatu yang terlalu mencolok...",
  ui_story_5066_50660402_31_dialog_content = "Permintaan yang aneh... Aku pikir jika ada yang bisa memanfaatkan kekuatanku, mereka pasti ingin memamerkan kekuatan mereka ke dunia.",
  ui_story_5066_50660402_32_dialog_content = "Tapi kamu... Yah, bukan masalah besar; kamu pasti bisa menjadi ratu yang low-profile jika itu yang kamu inginkan.",
  ui_story_5066_50660402_33_dialog_content = "O-Oke kalau begitu. Silakan ambil... harga berapapun yang kamu inginkan dariku...",
  ui_story_5066_50660402_34_dialog_content = "Harga?",
  ui_story_5066_50660402_35_dialog_content = "Kamu tidak akan mengambil mata atau hidungku? ... Atau mungkin kamu ingin telingaku?",
  ui_story_5066_50660402_36_dialog_content = "*isak* Aku tidak peduli jika kamu harus memakan aku... Asalkan aku bisa keluar dari situasi berbahaya ini...",
  ui_story_5066_50660402_37_dialog_content = "Saya pernah bilang sebelumnya... Saya tidak pernah mengonsumsi makhluk fana!",
  ui_story_5066_50660402_38_dialog_content = "Boo-hoo! Aku... Maaf! Aku benar-benar lupa...",
  ui_story_5066_50660402_39_dialog_content = "Aku tidak perlu kamu membayar apa pun.",
  ui_story_5066_50660402_40_dialog_content = "Membuat perjanjian denganmu hanya karena keunikanmu dan relik yang kamu pegang.",
  ui_story_5066_50660402_41_dialog_content = "Ketika lembar musik klarinet dimainkan, aku akan membantumu menguasai lautan.",
  ui_story_5066_50660402_42_dialog_content = "Dengan itu, apakah masih ada keraguan di benakmu?",
  ui_story_5066_50660402_43_dialog_content = "Oh... Sepertinya tidak...",
  ui_story_5066_50660402_44_dialog_content = "Tapi bukankah ini... Terlalu bagus untuk menjadi kenyataan...?",
  ui_story_5066_50660402_45_dialog_content = "Tidak perlu khawatir; Anda akan memulai bab baru dalam hidup. Nikmatilah sepenuhnya.",
  ui_story_5066_50660402_46_dialog_content = "<size=45>Saat ini, perjanjian resmi dibuat!</size>",
  ui_story_5066_50660402_47_dialog_content = "...",
  ui_story_5066_50660501_1_dialog_content = "<color=#e8d9bb>Klang—Klang—</color>",
  ui_story_5066_50660501_2_dialog_content = "Penjaga ini lebih tangguh dari yang kubayangkan.",
  ui_story_5066_50660501_3_dialog_content = "Tersedaklah pada rumput laut, kalian brengsek!",
  ui_story_5066_50660501_4_dialog_content = "<color=#e8d9bb>Klang—Retak—</color>",
  ui_story_5066_50660501_5_dialog_content = "Kamu tidak salah... Mereka cukup gigih...",
  ui_story_5066_50660501_6_dialog_content = "Tapi kita tidak bisa membiarkan mereka lolos melewati kita...",
  ui_story_5066_50660501_7_dialog_content = "Hah, itu cukup mengejutkan.",
  ui_story_5066_50660501_8_dialog_content = "Di perairan ini, benarkah ada yang berani menentang aku dan pengawal-pengawalku!?",
  ui_story_5066_50660501_9_dialog_content = "Sepertinya kunjungan saya ke sini hari ini sangat tepat waktu!",
  ui_story_5066_50660501_10_dialog_content = "Jika kita membiarkan ini, siapa tahu masalah apa yang bisa muncul?",
  ui_story_5066_50660501_11_dialog_content = "Pengawal, kalian kelaparan atau apa? Cepat bereskan kedua pengkhianat ini!",
  ui_story_5066_50660501_12_dialog_content = "<color=#e8d9bb>Klang—Retak—</color>",
  ui_story_5066_50660501_13_dialog_content = "Kamu seribu tahun terlalu dini untuk menantangku!",
  ui_story_5066_50660501_14_dialog_content = "Tapi aku mulai merasa sedikit bosan, jadi ayo kita bersenang-senang!",
  ui_story_5066_50660501_15_dialog_content = "<color=#e8d9bb>Klang—Retak—</color>",
  ui_story_5066_50660501_16_dialog_content = "Bertarung... Sebenarnya bukan masalah bagi kita...",
  ui_story_5066_50660501_17_dialog_content = "Aku hanya ingin tahu bagaimana Connolly saat ini...",
  ui_story_5066_50660501_18_dialog_content = "<color=#e8d9bb>Suara klarinet bergema.</color>",
  ui_story_5066_50660501_19_dialog_content = "Apa masalahnya dengan lagu seram ini?",
  ui_story_5066_50660501_20_dialog_content = "Hei, penjaga, pergi dan selidiki...",
  ui_story_5066_50660501_21_dialog_content = "...",
  ui_story_5066_50660501_22_dialog_content = "<size=45>Apa... apa ini?!</size>",
  ui_story_5066_50660501_23_dialog_content = "Apakah itu Connolly? Apa yang terjadi padanya?!",
  ui_story_5066_50660501_24_dialog_content = "Sepertinya... Dia mendapatkan kekuatan baru... Apakah dia melakukan ini hanya untuk membantu kita?",
  ui_story_5066_50660501_25_dialog_content = "Ha! Semua bualan; hanya terlihat menakutkan.",
  ui_story_5066_50660501_26_dialog_content = "Ini sebenarnya menghemat masalahku. Ayo, penjaga, pergi tangkap dia!",
  ui_story_5066_50660501_27_dialog_content = "*memainkan lagu*",
  ui_story_5066_50660501_28_dialog_content = "Huh... Aaaaah... apa ini tentakel-tentakel ini?!",
  ui_story_5066_50660501_29_dialog_content = "Tidak! Tolong! Turunkan aku!",
  ui_story_5066_50660501_30_dialog_content = "*memainkan lagu*",
  ui_story_5066_50660501_31_dialog_content = "Saya tidak berniat melakukannya... Saya hanya mengikuti perintah sang pangeran... Tolong, lepaskan saya!",
  ui_story_5066_50660501_32_dialog_content = "Aku juga tidak ingin bertarung denganmu! Ini... ini semua karena pangeran! Dia yang menyuruhku melakukannya!",
  ui_story_5066_50660501_33_dialog_content = "Berhenti! Siapa bilang kalian bisa kabur?! Kalian ini, bermanfaat amat, berhenti! Sialan...",
  ui_story_5066_50660501_34_dialog_content = "...",
  ui_story_5066_50660501_35_dialog_content = "Heh heh. Bagus, sangat bagus...",
  ui_story_5066_50660501_36_dialog_content = "Berani melawan saya, dan kau pasti akan membayar harganya!",
  ui_story_5066_50660501_37_dialog_content = "Lagipula, pajak yang dibayar oleh kota kecil yang bobrok ini sangat rendah untuk diawali.",
  ui_story_5066_50660501_38_dialog_content = "Jika kamu masih tidak patuh, aku tidak melihat alasan untuk keberadaan kota ini!",
  ui_story_5066_50660501_39_dialog_content = "...",
  ui_story_5066_50660501_40_dialog_content = "Hei, kamu... gadis berpenampilan aneh, cukup sudah!",
  ui_story_5066_50660501_41_dialog_content = "Jika sang pangeran kembali dan memberitahu raja untuk mengirim pasukan menghancurkan kota kita... bisakah kamu tanggung akibatnya?",
  ui_story_5066_50660501_42_dialog_content = "Lebih jauh lagi, yang kau sakiti adalah tidak lain adalah Pangeran bangsawan!",
  ui_story_5066_50660501_43_dialog_content = "Anda, dengan status rendah Anda, bagaimana bisa bersikap tidak sopan seperti itu?",
  ui_story_5066_50660501_44_dialog_content = "...",
  ui_story_5066_50660501_45_dialog_content = "(Aku tahu... Menonjol seperti ini memang tidak cocok untukku...)",
  ui_story_5066_50660501_46_dialog_content = "(Aku... melakukan kesalahan lagi, ya...?)",
  ui_story_5066_50660501_47_dialog_content = "(Jika saya hanya khawatir tentang bahaya yang ada di depan mata... Apakah akibatnya akan terus seburuk ini...?)",
  ui_story_5066_50660501_48_dialog_content = "Aku... Aku tidak bermaksud melakukan itu... T-Tapi...",
  ui_story_5066_50660501_49_dialog_content = "Hai, Connolly! Kamu tidak perlu minta maaf sama sekali kepada orang-orang sombong ini!",
  ui_story_5066_50660501_50_dialog_content = "Apakah kamu lupa bagaimana pangeran sombong itu menyerangmu? Kenapa kamu masih takut padanya?!",
  ui_story_5066_50660501_51_dialog_content = "Kamu akan terus diganggu seumur hidup jika tidak berubah!",
  ui_story_5066_50660501_52_dialog_content = "Toleransi dan kompromi... hanya akan membawa Anda sejauh ini...",
  ui_story_5066_50660501_53_dialog_content = "Itu memang tak terbantahkan...",
  ui_story_5066_50660501_54_dialog_content = "Benar! Lihat saja semua hal keterlaluan yang telah dilakukan sang pangeran di kota kecil ini!",
  ui_story_5066_50660501_55_dialog_content = "Kalau dia tidak ingin memimpin kita, tak masalah buatku!",
  ui_story_5066_50660501_56_dialog_content = "Sudah saatnya kita memilih pemimpin baru!",
  ui_story_5066_50660501_57_dialog_content = "...",
  ui_story_5066_50660501_58_dialog_content = "<size=33>Yah, aku rasa... apa yang dia katakan sebenarnya masuk akal...</size>",
  ui_story_5066_50660501_59_dialog_content = "<size=33>Jujur, saya juga sudah cukup...</size>",
  ui_story_5066_50660501_60_dialog_content = "Jika mereka menaikkan pajak lagi, kita tidak akan bertahan; ini akan jadi jalan buntu.",
  ui_story_5066_50660501_61_dialog_content = "Kalau bisa, kita juga bisa mencari pemimpin baru, bukan?",
  ui_story_5066_50660501_62_dialog_content = "<size=45>Keterlaluan, kalian semua keterlaluan!</size>",
  ui_story_5066_50660501_63_dialog_content = "Untuk berpikir bahwa kalian orang-orang rendahan bisa menggoyahkan kekuasaan kami hanya dengan beberapa kata? Itu tidak akan terjadi!",
  ui_story_5066_50660501_64_dialog_content = "Hari ini, saya akan memberi contoh dan mengeksekusi kalian semua pemberontak yang berbicara sembarangan!",
  ui_story_5066_50660501_65_dialog_content = "Um... Aku lah yang menyebabkan seluruh kekacauan ini...",
  ui_story_5066_50660501_66_dialog_content = "Semua orang barusan berbicara untukku...",
  ui_story_5066_50660501_67_dialog_content = "Tapi sekarang setelah aku memiliki kekuatan yang luar biasa ini... Aku... Aku bukan seperti dulu lagi...",
  ui_story_5066_50660501_68_dialog_content = "Kali ini... Giliranku untuk melindungi semua orang!",
  ui_story_5066_50660602_1_dialog_content = "<color=#e8d9bb>Plak—Plak!</color>",
  ui_story_5066_50660602_2_dialog_content = "Ah... sakit...",
  ui_story_5066_50660602_3_dialog_content = "<color=#e8d9bb>Plak—Plak!</color>",
  ui_story_5066_50660602_4_dialog_content = "Eek... tidak, tolong, berhenti!",
  ui_story_5066_50660602_5_dialog_content = "*memainkan lagu*",
  ui_story_5066_50660602_6_dialog_content = "Cukup... Itu sudah cukup!",
  ui_story_5066_50660602_7_dialog_content = "Aku kalah! Aku menyerah! Tidak... Aku tidak kalah darimu...",
  ui_story_5066_50660602_8_dialog_content = "Aku kalah melawan monster tentakel ini!",
  ui_story_5066_50660602_9_dialog_content = "Darimana di dunia ini kamu mendapatkan kekuatan seperti itu!?",
  ui_story_5066_50660602_10_dialog_content = "Yah... uh, aku tidak tahu bagaimana menjelaskan ini...",
  ui_story_5066_50660602_11_dialog_content = "Mungkin lebih baik kalian melihatnya sendiri?",
  ui_story_5066_50660602_12_dialog_content = "*memainkan lagu*",
  ui_story_5066_50660602_13_dialog_content = "...",
  ui_story_5066_50660602_14_dialog_content = "…?!",
  ui_story_5066_50660602_15_dialog_content = "Apa?! Ini...!",
  ui_story_5066_50660602_16_dialog_content = "Mungkinkah... yang dari legenda kuno itu, kuil...",
  ui_story_5066_50660602_17_dialog_content = "Tidak, tidak, tidak, benar-benar tidak mungkin! Bagaimana gadis aneh ini bisa...",
  ui_story_5066_50660602_18_dialog_content = "<color=#e8d9bb>Plak—Plak!</color>",
  ui_story_5066_50660602_19_dialog_content = "<color=#e8d9bb>Ciprat—</color>",
  ui_story_5066_50660602_20_dialog_content = "Ugh... Argh...",
  ui_story_5066_50660602_21_dialog_content = "Berani-beraninya... Berani-beraninya kau... Tunggu saja, tentara kerajaan akan datang ke sini... untuk menyelesaikan masalah ini dan menghapus aibku!",
  ui_story_5066_50660602_22_dialog_content = "Fyuh... Kayaknya aku akhirnya berhasil mengatasinya... benar, kan?",
  ui_story_5066_50660602_23_dialog_content = "Tentu saja kau bisa, Connolly! Cara kau menghantam pangeran itu sungguh keren! Percaya dirilah!",
  ui_story_5066_50660602_24_dialog_content = "Benar... Bahkan Dayna pun tidak bisa melakukan hal seperti itu...",
  ui_story_5066_50660602_25_dialog_content = "A-Aku... Itu tidak terlalu mengesankan... Tolong jangan mengolok-olokku, kalian berdua...",
  ui_story_5066_50660602_26_dialog_content = "Kami sama sekali tidak mengolok-olok kamu.",
  ui_story_5066_50660602_27_dialog_content = "Jadi apa sebenarnya benda itu, Connolly? Semacam monster?",
  ui_story_5066_50660602_28_dialog_content = "Dayna... Mungkin itu... Sedikit kasar...",
  ui_story_5066_50660602_29_dialog_content = "Ups, maaf ya! Lebih tepatnya temanmu, kan?",
  ui_story_5066_50660602_30_dialog_content = "Uh... Sejujurnya, aku juga tidak tahu apa itu...",
  ui_story_5066_50660602_31_dialog_content = "Tetapi terus menyebut dirinya sebagai \"Sang Penguasa Aqua Agung.\"",
  ui_story_5066_50660602_32_dialog_content = "Jadi menurutku... Itu pasti sosok yang cukup kuat, kan?",
  ui_story_5066_50660602_33_dialog_content = "<size=45>Aqua Lord? Ini... Aqua Lord?!</size>",
  ui_story_5066_50660602_34_dialog_content = "Hah? Maaf... Apakah Anda kenal dengan Aqua Lord?",
  ui_story_5066_50660602_35_dialog_content = "Aqua Lord... Dia adalah penguasa hebat yang pernah menguasai dunia bawah air!",
  ui_story_5066_50660602_36_dialog_content = "Sebelum Raja Merman yang kejam datang ke perairan dangkal, dia dulu menguasai segalanya di sini...",
  ui_story_5066_50660602_37_dialog_content = "Kabarnya hingga saat ini, reruntuhan kuil dengan kekuatan tersembunyi masih ada.",
  ui_story_5066_50660602_38_dialog_content = "<anim type=Shake>ç åï|'H>■...</anim>",
  ui_story_5066_50660602_39_dialog_content = "Kata-kata suci, ini kata-kata suci! Tuhan akan memberikan kata-kata suci kepada kita...",
  ui_story_5066_50660602_40_dialog_content = "...",
  ui_story_5066_50660602_41_dialog_content = "<color=#e8d9bb>Gedebuk-</color>",
  ui_story_5066_50660602_42_dialog_content = "<color=#e8d9bb>Dengan tatapan penuh keyakinan, pria tua itu berlutut dengan penuh penghormatan...</color>",
  ui_story_5066_50660602_43_dialog_content = "<color=#e8d9bb>Seperti ombak, penduduk laut yang lain mulai bersujud di hadapan penguasa agung yang pernah ada ini...</color>",
  ui_story_5066_50660701_1_dialog_content = "Ini semua salahmu karena mengirim Connolly untuk mengurus urusan, dan sekarang jadi bencana total!",
  ui_story_5066_50660701_2_dialog_content = "Bagaimana bisa aku tahu bahwa dia akan... berani menjadi begitu ceroboh dan pemberontak?",
  ui_story_5066_50660701_3_dialog_content = "Jika ini mempengaruhi karier anak kita, tidak ada cara kamu bisa menebusnya.",
  ui_story_5066_50660701_4_dialog_content = "Berhenti membicarakannya; cukup berhenti! Kutukan ini, begitu kita menemukannya, kita harus memberinya pelajaran yang baik!",
  ui_story_5066_50660701_5_dialog_content = "...",
  ui_story_5066_50660701_6_dialog_content = "Apa yang terjadi? Kenapa semua orang berlutut di tanah?",
  ui_story_5066_50660701_7_dialog_content = "Lihat... lihat ke sana.",
  ui_story_5066_50660701_8_dialog_content = "<anim type=Shake>âŠâ €په؛‹Šèã</anim>",
  ui_story_5066_50660701_9_dialog_content = "Itu... Saya pernah mendengarnya. Itu adalah Sang Penguasa Agung dari masa lalu!",
  ui_story_5066_50660701_10_dialog_content = "Dan di samping tuan adalah... Connolly?! Bagaimana itu mungkin?",
  ui_story_5066_50660701_11_dialog_content = "Jangan khawatir tentang apakah itu mungkin atau tidak. Berlututlah dengan cepat, atau kita yang akan berada dalam masalah!",
  ui_story_5066_50660701_12_dialog_content = "<color=#e8d9bb>Gedebuk-</color>",
  ui_story_5066_50660701_13_dialog_content = "<anim type=Shake>е­‘гдё —пе›Œâ€¦в¦</anim>",
  ui_story_5066_50660701_14_dialog_content = "Meskipun ada banyak suara berbeda dari kerumunan barusan...",
  ui_story_5066_50660701_15_dialog_content = "Sepertinya semua orang lebih atau kurang menerima Aqua Lord ini.",
  ui_story_5066_50660701_16_dialog_content = "Masalahnya, sepertinya... adalah tidak ada yang bisa mengerti apa yang dikatakannya.",
  ui_story_5066_50660701_17_dialog_content = "Kita mungkin tidak bisa mengerti, tapi seharusnya tidak menjadi masalah untuk Connolly!",
  ui_story_5066_50660701_18_dialog_content = "Bisa tolong terjemahkan untuk kami?",
  ui_story_5066_50660701_19_dialog_content = "Oh... Aku tidak sadar bahwa tidak ada orang lain yang bisa memahami...",
  ui_story_5066_50660701_20_dialog_content = "Ucapannya memiliki efek yang sama seperti melodi partitur musik sebelumnya...",
  ui_story_5066_50660701_21_dialog_content = "Apakah ini... alasan mengapa aku dipilih?",
  ui_story_5066_50660701_22_dialog_content = "W-Yah... Jika tidak ada yang keberatan...",
  ui_story_5066_50660701_23_dialog_content = "Aku akan menerjemahkan kata-kata Aqua Lord agar semua orang bisa mendengarnya...",
  ui_story_5066_50660701_24_dialog_content = "<anim type=Shake>éµè Œâ€...¦â€¦ å“š■</anim>",
  ui_story_5066_50660701_25_dialog_content = "Aqua Lord mengatakan bahwa ia ingin kembali ke dunia ini dan merebut kembali kota ini dari Raja Merman yang merebut tahta.",
  ui_story_5066_50660701_26_dialog_content = "<anim type=Shake>FzI¦م€ ...■چcJ;@ڑ â– é‡Œ</anim>",
  ui_story_5066_50660701_27_dialog_content = "Dan... Karena kemampuan bawaan saya untuk berkomunikasi dengannya, Aqua Lord membentuk sebuah perjanjian dengan saya...",
  ui_story_5066_50660701_28_dialog_content = "Untuk menjadi utusan dan menjalankan kehendaknya...",
  ui_story_5066_50660701_29_dialog_content = "<anim type=Shake>… …و°i%µç·tu€…â€i... €¦…وˆگم€■</anim>",
  ui_story_5066_50660701_30_dialog_content = "Hah...?!",
  ui_story_5066_50660701_31_dialog_content = "(Uh-oh...)",
  ui_story_5066_50660701_32_dialog_content = "(Ini ingin aku memberi tahu semua orang... Bahwa aku adalah Aqua Queen...?)",
  ui_story_5066_50660701_33_dialog_content = "(Aku tidak yakin... bisa bilang sesuatu seperti itu...)",
  ui_story_5066_50660701_34_dialog_content = "(Saya sudah bilang... Bahwa saya tidak ingin melakukan sesuatu yang akan membuat saya menonjol...)",
  ui_story_5066_50660701_35_dialog_content = "<anim type=Shake>еâ€...eåŸœ■å€âŠâ</anim>",
  ui_story_5066_50660701_36_dialog_content = "<size=33>Cukup, Aqua Lord... Jika ada tuntutan lagi, kamu hanya akan menakutkan semua orang...</size>",
  ui_story_5066_50660701_37_dialog_content = "... (tidak senang)",
  ui_story_5066_50660701_38_dialog_content = "Anu... Uh...",
  ui_story_5066_50660701_39_dialog_content = "S-semuanya baik-baik saja... Jika saya berhenti menerjemahkan sekarang?",
  ui_story_5066_50660701_40_dialog_content = "...",
  ui_story_5066_50660701_41_dialog_content = "Tentu saja, Pembicara Ilahi! Atau seharusnya kami menyebut Anda sebagai... Queen?",
  ui_story_5066_50660701_42_dialog_content = "<size=45>Uhhh... Queen?!</size>",
  ui_story_5066_50660701_43_dialog_content = "I-Itu sedikit berani, menurut kamu...?",
  ui_story_5066_50660701_44_dialog_content = "<size=33>Aku bahkan tidak menerjemahkan bagian terakhir itu, tapi entah bagaimana... Semua orang sudah mulai... memanggilku \"ratu\"?</size>",
  ui_story_5066_50660701_45_dialog_content = "Benar sekali, Yang Mulia, kekuasaan Anda terlihat jelas oleh semua orang!",
  ui_story_5066_50660701_46_dialog_content = "Penjaga Merman yang menjijikkan itu berkeliaran di sekitar. Kamu seharusnya benar-benar memberi mereka pelajaran!",
  ui_story_5066_50660701_47_dialog_content = "Kamu memiliki dukungan penuh dari kami!",
  ui_story_5066_50660701_48_dialog_content = "Oh... Yah, kalau keadaannya akan seperti ini...",
  ui_story_5066_50660701_49_dialog_content = "Bahkan jika aku tidak melakukannya demi orang lain, atau bahkan demi diriku sendiri...",
  ui_story_5066_50660701_50_dialog_content = "Aku masih ingin menyelesaikan bersih-bersih di sekitar sini...",
  ui_story_5066_50660702_1_dialog_content = "<color=#e8d9bb>Plak—Plak!</color>",
  ui_story_5066_50660702_2_dialog_content = "Fyuh... Itu tadi yang terakhir. Pengawal Merman itu seharusnya sudah pergi sekarang...",
  ui_story_5066_50660702_3_dialog_content = "Preman-preman busuk itu seharusnya sudah diusir dari kota sejak lama!",
  ui_story_5066_50660702_4_dialog_content = "Sayangnya, kue milik Connolly tidak berhasil. Sungguh mengecewakan...",
  ui_story_5066_50660702_5_dialog_content = "Hai Connolly... Kamu tampaknya tidak terlalu bahagia... Apa semuanya baik-baik saja?",
  ui_story_5066_50660702_6_dialog_content = "Oh, maaf! Kau bisa tahu hanya dengan melihatnya, ya...?",
  ui_story_5066_50660702_7_dialog_content = "Baru saja... Semua orang mulai memanggil saya ratu mereka...",
  ui_story_5066_50660702_8_dialog_content = "Tapi... Aku tidak ingin menjadi ratu aneh seperti ini...",
  ui_story_5066_50660702_9_dialog_content = "Aku... aku lebih suka menghabiskan hari-hariku sendirian di loteng, hanya ditemani oleh musikku saja...",
  ui_story_5066_50660702_10_dialog_content = "Aku tidak begitu paham, tapi aku sepenuh hati mendukung keputusanmu.",
  ui_story_5066_50660702_11_dialog_content = "Tapi... Orang ikan...",
  ui_story_5066_50660702_12_dialog_content = "Tidak apa-apa, Robyn. Jangan takut Connolly.",
  ui_story_5066_50660702_13_dialog_content = "Tidak apa-apa... Aku sadar situasi yang aku hadapi...",
  ui_story_5066_50660702_14_dialog_content = "Raja Merman... Dia tidak akan membiarkan aku pergi begitu saja, bukan?",
  ui_story_5066_50660702_15_dialog_content = "...",
  ui_story_5066_50660702_16_dialog_content = "Tsk, jangan khawatir! Robyn dan aku akan melindungimu!",
  ui_story_5066_50660702_17_dialog_content = "Benar... Bagaimanapun, kamu selalu sangat baik kepada kami.",
  ui_story_5066_50660702_18_dialog_content = "Kami berniat membayar Anda tadi, tapi Anda malah menyelamatkan kami lagi...",
  ui_story_5066_50660702_19_dialog_content = "Tapi... Tapi saya hanya melakukan tugas saya.",
  ui_story_5066_50660702_20_dialog_content = "Aqua Lord menolongku saat aku dalam bahaya... Jadi aku harus membalasnya dengan menjalankan keinginannya...",
  ui_story_5066_50660702_21_dialog_content = "Lagi pula... Tidak ada yang diambil dariku saat kita membentuk pakta kita...",
  ui_story_5066_50660702_22_dialog_content = "Keinginannya? Maksudmu kamu akan membantu merebut kembali kota ini?!",
  ui_story_5066_50660702_23_dialog_content = "Ya... Jadi, bisakah kamu menceritakan semua yang kamu tahu tentang Raja Merman?",
  ui_story_5066_50660702_24_dialog_content = "Tentu saja! Robyn lebih pandai menjelaskan hal ini, jadi akan kubiarkan dia melakukannya.",
  ui_story_5066_50660702_25_dialog_content = "Baiklah Dayna, tapi kamu masih perlu membantu aku mengisi kekosongan...",
  ui_story_5066_50660702_26_dialog_content = "Kurasa kita harus mulai dari awal sekali.",
  ui_story_5066_50660702_27_dialog_content = "Raja Merman adalah... Seorang pria yang mulia yang berasal dari Dangkal...",
  ui_story_5066_50660702_28_dialog_content = "Dan menyatakan dirinya sebagai penguasa semua jenis ikan.",
  ui_story_5066_50660702_29_dialog_content = "Pria itu sangat percaya pada supremasi Dangkal, jadi dia meremehkan semua ras lain yang hidup di dasar laut.",
  ui_story_5066_50660702_30_dialog_content = "Itulah mengapa dia menggunakan kekejaman dan kekerasan saat memerintah kota-kota kecil seperti ini.",
  ui_story_5066_50660702_31_dialog_content = "Itulah sebabnya... Dia jarang menampakkan diri di sekitar sini.",
  ui_story_5066_50660702_32_dialog_content = "Sedangkan Pangeran Merman... adalah penerusnya, sekaligus orang yang ia tunjuk untuk mengumpulkan pajak dari kita.",
  ui_story_5066_50660702_33_dialog_content = "Meskipun pangeran itu terlihat seperti seorang idiot...",
  ui_story_5066_50660702_34_dialog_content = "Kita tidak boleh lupa bahwa dia adalah orang terkemuka dari Dangkal, sebuah area yang kaya akan sumber daya dan teknologi canggih...",
  ui_story_5066_50660702_35_dialog_content = "Kelicikan dan senjata yang dimilikinya tidak boleh diremehkan.",
  ui_story_5066_50660702_36_dialog_content = "Yang juga berarti Raja Merman itu lebih menakutkan lagi.",
  ui_story_5066_50660702_37_dialog_content = "Tadi kamu tidak bilang jangan menakutinya...?",
  ui_story_5066_50660702_38_dialog_content = "Maksud saya, jika kita akan pergi bertarung, maka sebenarnya tak ada gunanya lagi berbasa-basi.",
  ui_story_5066_50660702_39_dialog_content = "Huu-huu...",
  ui_story_5066_50660702_40_dialog_content = "Aku... Aku sangat berterima kasih kepada kalian berdua karena sudah menceritakan semua ini padaku...",
  ui_story_5066_50660702_41_dialog_content = "Tapi... Apakah aku benar-benar punya peluang melawan seseorang yang sekuat Raja Merman?",
  ui_story_5066_50660702_42_dialog_content = "...",
  ui_story_5066_50660702_43_dialog_content = "Jangan takut, Connolly. Kamu dan Aqua Lord jauh lebih kuat daripada mereka semua...",
  ui_story_5066_50660702_44_dialog_content = "Tidak hanya itu, kami akan selalu di sisi Anda...",
  ui_story_5066_50660702_45_dialog_content = "Benar sekali! Kita hanya perlu menunggu kamu menjadi Queen!",
  ui_story_5066_50660702_46_dialog_content = "Dan saat hari itu tiba, kami akan menjadi pengawal kerajaanmu!",
  ui_story_5066_50660702_47_dialog_content = "Satu di kiri Anda... Dan satu di kanan Anda.",
  ui_story_5066_50660702_48_dialog_content = "Tak pernah terlalu jauh dari sisimu...",
  ui_story_5066_50660702_49_dialog_content = "Dengan begitu, kami bisa membantu Anda kapanpun Anda membutuhkannya, bukan?",
  ui_story_5066_50660702_50_dialog_content = "Kami juga akan membantu kalian merebut kembali kendali atas kota ini!",
  ui_story_5066_50660702_51_dialog_content = "Kamu tidak bisa meninggalkanku jika kamu akan melakukan sesuatu yang keren seperti itu!",
  ui_story_5066_50660702_52_dialog_content = "Lagipula, aku sudah ingin menghapus ekspresi sombong dari wajah raja itu sejak beberapa waktu lalu!",
  ui_story_5066_50660702_53_dialog_content = "Semua... Aku benar-benar tidak tahu... Bagaimana cara membalas kebaikan kalian...",
  ui_story_5066_50660702_54_dialog_content = "Tapi dengan bantuanmu, saya tahu saya tidak perlu takut.",
  ui_story_5066_50660702_55_dialog_content = "Jadi tolong... Tolong pinjamkan kekuatanmu padaku...!",
  ui_story_5066_50660801_1_dialog_content = "*memainkan klarinet*",
  ui_story_5066_50660801_2_dialog_content = "...",
  ui_story_5066_50660801_3_dialog_content = "Aduh! ... Meskipun ini bukan pertama kalinya aku memanggilnya, aku tetap merasa sedikit takut...",
  ui_story_5066_50660801_4_dialog_content = "Eh... M-maaf memanggilmu lagi begitu cepat...",
  ui_story_5066_50660801_5_dialog_content = "Aku hanya ingin memberitahumu... bahwa aku siap dan bersedia untuk menjalankan keinginanmu.",
  ui_story_5066_50660801_6_dialog_content = "Saya sangat senang dengan keputusan Anda.",
  ui_story_5066_50660801_7_dialog_content = "Jadi, mari kita jadikan pakta ini resmi.",
  ui_story_5066_50660801_8_dialog_content = "Hah...? Tapi kukira kita sudah membentuk pakta kita?",
  ui_story_5066_50660801_9_dialog_content = "Aku adalah Aqua Lord yang kuno... dan agung. Sebuah pakta sementara di medan perang hanyalah langkah darurat.",
  ui_story_5066_50660801_10_dialog_content = "Ini tidak pantas bagi status terhormat saya.",
  ui_story_5066_50660801_11_dialog_content = "Oh... Oke. Jadi bagaimana kita harus melakukannya...?",
  ui_story_5066_50660801_12_dialog_content = "Dengan klarinetmu sebagai peninggalan, mari kita formalisasikan.",
  ui_story_5066_50660801_13_dialog_content = "Dengan cara ini, aku bisa selalu di sisimu.",
  ui_story_5066_50660801_14_dialog_content = "Oke, jadi begini...?",
  ui_story_5066_50660801_15_dialog_content = "*memainkan lagu*",
  ui_story_5066_50660801_16_dialog_content = "Baiklah, ini merupakan pakta resmi.",
  ui_story_5066_50660801_17_dialog_content = "Sebagai Queen, menjadi kewajiban Anda untuk mengelola kota atas nama saya.",
  ui_story_5066_50660801_18_dialog_content = "Oh... Aku akan berusaha sebaik mungkin, meskipun belum pernah melakukan hal seperti ini sebelumnya...",
  ui_story_5066_50660801_19_dialog_content = "Juga, bangun kembali kuil tersebut.",
  ui_story_5066_50660801_20_dialog_content = "Untuk mengembalikan kekuatanku dalam menghadapi serangan yang akan datang dari Raja Merman.",
  ui_story_5066_50660801_21_dialog_content = "Uh... Kuil apa?",
  ui_story_5066_50660801_22_dialog_content = "Aku pernah menyebutkan ini sebelumnya, tapi kamu... salah mengartikannya.",
  ui_story_5066_50660801_23_dialog_content = "Saya tidak tahu bagaimana mengatakannya... sepertinya kita akan membuat semua orang bekerja keras.",
  ui_story_5066_50660801_24_dialog_content = "Tapi... Aku janji akan mencari solusi...",
  ui_story_5066_50660801_25_dialog_content = "Jadi, uh... Jenis kuil apa yang kamu inginkan?",
  ui_story_5066_50660801_26_dialog_content = "Untuk menghormati saya, Aqua Lord yang agung, ada persyaratan tentang skala kuilku yang harus kamu ingat di benakmu.",
  ui_story_5066_50660801_27_dialog_content = "Ba-baik!",
  ui_story_5066_50660801_28_dialog_content = "Pertama-tama, tempat itu harus seagung gereja tempat iblis malam tinggal.",
  ui_story_5066_50660801_29_dialog_content = "\"Iblis nokturnal\"? Hmm... Sebuah kuil besar... Uh-huh, mengerti.",
  ui_story_5066_50660801_30_dialog_content = "Seharusnya se-misterius Rumah Sang Penyihir...",
  ui_story_5066_50660801_31_dialog_content = "\"Se-misterius rumah penyihir...\"",
  ui_story_5066_50660801_32_dialog_content = "Ya, itu seharusnya cocok dengan baik!",
  ui_story_5066_50660801_33_dialog_content = "Seharusnya memiliki pesona kuno dari sebuah kastil yang sesat.",
  ui_story_5066_50660801_34_dialog_content = "Kastil kuno? Kamu memiliki selera yang baik dalam arsitektur, Aqua Lord...",
  ui_story_5066_50660801_35_dialog_content = "Seharusnya berkilau dalam kegelapan seperti Trapezohedron yang bersinar.",
  ui_story_5066_50660801_36_dialog_content = "Sebuah kuil yang bercahaya di kegelapan... Terdengar seperti sesuatu dari dongeng, tapi aku agak menyukai itu...",
  ui_story_5066_50660801_37_dialog_content = "Itu seharusnya saja... Apakah kamu paham sepenuhnya?",
  ui_story_5066_50660801_38_dialog_content = "Aku kira ini akan jauh lebih rumit... Tapi ternyata tidak terlalu sulit untuk dipahami!",
  ui_story_5066_50660801_39_dialog_content = "Jadi, uh... Kamu ingin kastil besar, kuno, magis, dan bercahaya di kegelapan, kan?",
  ui_story_5066_50660801_40_dialog_content = "…?",
  ui_story_5066_50660801_41_dialog_content = "Aku tidak punya banyak pengalaman dalam hal ini... Tapi tolong percaya padaku...",
  ui_story_5066_50660801_42_dialog_content = "Dan aku janji padamu... Aku akan membangun sebuah kuil yang bisa membuatmu bangga!",
  ui_story_5066_50660801_43_dialog_content = "Semoga kamu bisa memenuhi janji itu.",
  ui_story_5066_50660801_44_dialog_content = "Baiklah…",
  ui_story_5066_50660801_45_dialog_content = "Ada apa, Connolly?",
  ui_story_5066_50660801_46_dialog_content = "Kamu baru saja membentuk pakta resmi dengan Aqua Lord... Tapi sepertinya kamu tidak terlalu bahagia?",
  ui_story_5066_50660801_47_dialog_content = "Yah, memang baru saja memberiku quest yang sangat sulit...",
  ui_story_5066_50660801_48_dialog_content = "Mengelola sebuah kota, membangun sebuah kuil... Aku belum pernah melakukan hal seperti ini sebelumnya...",
  ui_story_5066_50660801_49_dialog_content = "Tidak ada alasan untuk khawatir! Anda hanya belum mencoba, itu saja!",
  ui_story_5066_50660801_50_dialog_content = "Setelah kamu mencoba, kamu akan menemukan bahwa itu tidak sesulit yang kamu kira. Kamu selalu punya bakat seperti itu.",
  ui_story_5066_50660801_51_dialog_content = "Tidak hanya itu... Kami dan penduduk kota akan membantu Anda sebisanya...",
  ui_story_5066_50660801_52_dialog_content = "Jika itu berarti menggoyahkan kekuasaan Raja Merman... Saya yakin semua orang akan bersemangat untuk membantu.",
  ui_story_5066_50660801_53_dialog_content = "Benar, dan yang perlu kamu lakukan hanyalah memenuhi harapan mereka.",
  ui_story_5066_50660801_54_dialog_content = "B... Benarkah?",
  ui_story_5066_50660801_55_dialog_content = "Lalu... Aku juga akan mencoba dengan segala yang aku punya...",
  ui_story_5066_50660801_56_dialog_content = "<color=#e8d9bb>Gedebuk-</color>",
  ui_story_5066_50660801_57_dialog_content = "Yang Mulia, saya mohon ampun!",
  ui_story_5066_50660801_58_dialog_content = "Pengampunan saya? Anak saya mengalami kekejaman seperti itu, dan...",
  ui_story_5066_50660801_59_dialog_content = "Yang menyerangnya itu sepupumu, 'kan?",
  ui_story_5066_50660801_60_dialog_content = "Yah... itu hanya anak aneh yang diadopsi keluarga kami, pada dasarnya... kami tidak ada hubungan darah!",
  ui_story_5066_50660801_61_dialog_content = "Nah, jika itu masalahnya, kamu juga tidak berharga bagi saya. Pengawal...",
  ui_story_5066_50660801_62_dialog_content = "Tunggu! Aku tahu kelemahannya... Jika kalian pergi berperang, aku bisa menjamin kemenangan kalian!",
  ui_story_5066_50660801_63_dialog_content = "…?",
  ui_story_5066_50660801_64_dialog_content = "Lanjutkan, aku mendengarkan.",
  ui_story_5066_50660801_65_dialog_content = "Dia... hanya gadis biasa. Kekuatan klarinetlah yang membuatnya begitu tangguh.",
  ui_story_5066_50660801_66_dialog_content = "A... Aku, sebagai sepupunya, bisa membantu kamu mencuri klarinet itu!",
  ui_story_5066_50660801_67_dialog_content = "Lalu, penduduk kota itu tidak lebih dari sekumpulan orang yang tergantung pada belas kasihanmu.",
  ui_story_5066_50660801_68_dialog_content = "Apakah kamu berkata jujur?",
  ui_story_5066_50660801_69_dialog_content = "Benar sekali, Yang Mulia.",
  ui_story_5066_50660801_70_dialog_content = "Baiklah, akan kuberi kesempatan untuk melakukannya, tapi jika tidak berhasil...",
  ui_story_5066_50660801_71_dialog_content = "Saya bersedia menerima hukuman!",
  ui_story_5066_50660901_1_dialog_content = "Fiuh... Akhirnya pekerjaan hari ini selesai juga...",
  ui_story_5066_50660901_2_dialog_content = "Hanya menangani semua masalah orang-orang... Sudah cukup membuat kepala saya pusing...",
  ui_story_5066_50660901_3_dialog_content = "Noo-hoo... Bagaimana caranya aku harus membangun candi di atas segalanya ini...?",
  ui_story_5066_50660901_4_dialog_content = "Aku merindukan lotengku... Dan musikku...",
  ui_story_5066_50660901_5_dialog_content = "Kerja bagus hari ini, Connolly!",
  ui_story_5066_50660901_6_dialog_content = "Kamu juga, Dayna...",
  ui_story_5066_50660901_7_dialog_content = "Tanpa kamu dan Robyn... Aku tidak tahu apa yang akan kulakukan...",
  ui_story_5066_50660901_8_dialog_content = "Jangan terlalu rendah hati... Menurut pendapat saya, Anda melakukan pekerjaan yang fantastis sebagai utusan Aqua Lord.",
  ui_story_5066_50660901_9_dialog_content = "Hah... S-Sungguh...?",
  ui_story_5066_50660901_10_dialog_content = "Tapi jika kalian berdua tidak ada di sini... Aku bahkan tidak akan memiliki keberanian untuk berbicara dengan penduduk kota...",
  ui_story_5066_50660901_11_dialog_content = "Tidak masalah. Toh, kita semua pandai dalam hal yang berbeda-beda.",
  ui_story_5066_50660901_12_dialog_content = "Dan kami akan membantu kamu... dalam hal-hal yang kamu kurang ahli...",
  ui_story_5066_50660901_13_dialog_content = "Terutama pertempuran! Serahkan hal itu pada kami!",
  ui_story_5066_50660901_14_dialog_content = "Saya mengerti... Terima kasih semuanya atas dorongan yang diberikan...",
  ui_story_5066_50660901_15_dialog_content = "Kalau begitu, jika tidak ada hal lain untuk hari ini, kami akan pergi sekarang.",
  ui_story_5066_50660901_16_dialog_content = "Istirahat yang cukup, Connolly... Setelah semua, besok... sepertinya juga akan cukup sibuk...",
  ui_story_5066_50660901_17_dialog_content = "Ya... Akan melakukan.",
  ui_story_5066_50660901_18_dialog_content = "...",
  ui_story_5066_50660901_19_dialog_content = "*linglung* Hmm...",
  ui_story_5066_50660901_20_dialog_content = "...",
  ui_story_5066_50660901_21_dialog_content = "Ah...! A-Aqua Tuan...?",
  ui_story_5066_50660901_22_dialog_content = "Tolong jangan muncul di belakangku begitu tiba-tiba... Kamu benar-benar menakutkanku...",
  ui_story_5066_50660901_23_dialog_content = "Aku hanya khawatir tentang kemajuan konstruksi kuilku.",
  ui_story_5066_50660901_24_dialog_content = "Oh... Eh... Tentang itu...",
  ui_story_5066_50660901_25_dialog_content = "Aku tidak paham...",
  ui_story_5066_50660901_26_dialog_content = "Hah? Maksudmu...?",
  ui_story_5066_50660901_27_dialog_content = "Kamu sudah memiliki kekuatan absolut yang luar biasa.",
  ui_story_5066_50660901_28_dialog_content = "Cukup gunakan kekuatanmu untuk membuat penghuni bawah laut ini membangun kuilku dan mengusir musuh untukmu.",
  ui_story_5066_50660901_29_dialog_content = "Jadi, mengapa kamu begitu peduli tentang kehidupan mereka?",
  ui_story_5066_50660901_30_dialog_content = "Um... Apakah itu cara Anda dulu memerintah orang-orang bawah laut, Aqua Lord?",
  ui_story_5066_50660901_31_dialog_content = "Apakah ada yang salah dengan itu?",
  ui_story_5066_50660901_32_dialog_content = "Nah, orang-orang ini... Mereka semua memiliki pikiran dan emosi mereka sendiri. Mereka adalah makhluk hidup, bukan alat...",
  ui_story_5066_50660901_33_dialog_content = "Alasan mereka sangat tidak puas dengan Raja Merman saat ini adalah karena dia juga memperlakukan mereka seperti barang yang dapat dikorbankan...",
  ui_story_5066_50660901_34_dialog_content = "Jika kita memperlakukan mereka dengan cara yang sama... Mereka tidak akan mendukung kita seperti mereka mendukung kita sekarang.",
  ui_story_5066_50660901_35_dialog_content = "...",
  ui_story_5066_50660901_36_dialog_content = "Um... Apakah kamu... mengerti apa yang coba kukatakan?",
  ui_story_5066_50660901_37_dialog_content = "Saya percaya pada kekuatan absolut, dan kata-kata Anda tidak bisa meyakinkan saya...",
  ui_story_5066_50660901_38_dialog_content = "Oh... Lalu bagaimana cara menjelaskannya, ya...?",
  ui_story_5066_50660901_39_dialog_content = "Ah... Aku paham...",
  ui_story_5066_50660901_40_dialog_content = "Kita dulu berkomunikasi melalui klarinet ini sebelumnya... Benar?",
  ui_story_5066_50660901_41_dialog_content = "Maka izinkan aku memainkan lagu yang berjudul \"Rumah\" untukmu.",
  ui_story_5066_50660901_42_dialog_content = "Ini lagu favoritku. Dulu ibuku mengajarkannya padaku...",
  ui_story_5066_50660901_43_dialog_content = "Semoga ini membuatmu lebih paham tentang pemikiranku...",
  ui_story_5066_50660901_44_dialog_content = "Aku... menantikannya.",
  ui_story_5066_50660901_45_dialog_content = "Baiklah, aku siap...",
  ui_story_5066_50660901_46_dialog_content = "*memainkan lagu*",
  ui_story_5066_50660901_47_dialog_content = "*memainkan lagu*",
  ui_story_5066_50660901_48_dialog_content = "*memainkan lagu*",
  ui_story_5066_50660901_49_dialog_content = "*memainkan lagu*",
  ui_story_5066_50660901_50_dialog_content = "Ahh... Musik Mama selalu yang paling menenangkan saya...",
  ui_story_5066_50660901_51_dialog_content = "...",
  ui_story_5066_50660901_52_dialog_content = "Oh... Maaf, sepertinya aku... terlalu larut dalam situasi itu.",
  ui_story_5066_50660901_53_dialog_content = "Tidak apa-apa... Aku sangat terharu.",
  ui_story_5066_50660901_54_dialog_content = "Saya mengerti. Anda tidak melihat kota bawah air ini sebagai tempat untuk diperintah, melainkan sebagai... rumah Anda.",
  ui_story_5066_50660901_55_dialog_content = "Meski menghadapi sikap tidak ramah, kamu tidak menyimpan dendam karena kamu, yang kehilangan orang tua, telah menemukan tempat untuk merasa diterima.",
  ui_story_5066_50660901_56_dialog_content = "Kamu tidak berjuang untuk keinginanmu; kamu berjuang untuk melindungi kota yang memberimu perlindungan.",
  ui_story_5066_50660901_57_dialog_content = "Oh... Itu benar-benar bukan hal yang istimewa, kok...",
  ui_story_5066_50660901_58_dialog_content = "Aku hanya... Aku hanya berpikir bahwa akan sangat baik jika semua orang bisa hidup bahagia di tempat yang bisa mereka sebut milik mereka sendiri, itu saja...",
  ui_story_5066_50660901_59_dialog_content = "Semua orang bekerja keras untuk membangun candi untukmu, jadi... Aku harap ini juga terasa seperti rumah bagimu!",
  ui_story_5066_50660901_60_dialog_content = "...",
  ui_story_5066_50660901_61_dialog_content = "Mungkin membuat perjanjian dengan kamu adalah pilihan yang paling benar yang pernah saya buat selama bertahun-tahun.",
  ui_story_5066_50660901_62_dialog_content = "Aku akan menunggu dengan penuh antisipasi untuk... rumah yang akan kau sediakan untukku.",
  ui_story_5066_50660901_63_dialog_content = "Fiuh…",
  ui_story_5066_50660901_64_dialog_content = "Membantu semua orang menyelesaikan masalah mereka membuatku merasa senang dan bahagia...",
  ui_story_5066_50660901_65_dialog_content = "Tapi aku masih lebih suka menikmati waktu sendirianku di malam hari.",
  ui_story_5066_50660901_66_dialog_content = "...",
  ui_story_5066_50660901_67_dialog_content = "Hah? Ini sudah larut malam... Siapa yang masih mencari aku di jam seperti ini...?",
  ui_story_5066_50660901_68_dialog_content = "Hmm... Mungkin aku harus pura-pura tidur...",
  ui_story_5066_50660901_69_dialog_content = "Tidak, aku akan merasa bersalah jika melakukannya. Aku hanya akan pergi melihat-lihat saja...",
  ui_story_5066_50660901_70_dialog_content = "<color=#e8d9bb>Memukul—</color>",
  ui_story_5066_50660901_71_dialog_content = "H-hei! Tidak perlu kasar... Aku sedang dalam perjalanan!",
  ui_story_5066_50660901_72_dialog_content = "...",
  ui_story_5066_50660901_73_dialog_content = "Siapa kamu...? Dan bagaimana kamu bisa masuk ke sini...?",
  ui_story_5066_50660901_74_dialog_content = "Hah?! Apa yang terjadi...? Kenapa kamu... memegang klarinetku di tanganmu?!",
  ui_story_5066_50660901_75_dialog_content = "Ck, tertangkap begitu cepat...",
  ui_story_5066_50660901_76_dialog_content = "Sebagai penduduk kota yang berdedikasi, saya melakukan ini demi kebaikan Anda, Queen Connolly!",
  ui_story_5066_50660901_77_dialog_content = "Kamu bisa berbicara dengan monster itu semua karena benda ini, ya?",
  ui_story_5066_50660901_78_dialog_content = "Ini bukan hanya barang biasa... In-Ini adalah pusaka dari ibuku! Ini sangat penting bagi saya!",
  ui_story_5066_50660901_79_dialog_content = "Saya tidak peduli apakah itu peninggalan atau bukan; jika kita membiarkan Anda mengamuk seperti ini, seluruh kota akan menanggung akibatnya!",
  ui_story_5066_50660901_80_dialog_content = "Namun, jika saya menyerahkan benda ini kepada Raja Merman, kamu dan pengikutmu tidak akan bisa membuat masalah. Heh-heh...",
  ui_story_5066_50660901_81_dialog_content = "Siap-siaplah untuk menghadapi serangan pasukan Raja Merman yang akan menghancurkan kota bodoh ini!",
  ui_story_5066_50660901_82_dialog_content = "T-Tunggu...!",
  ui_story_5066_50660901_83_dialog_content = "Tolong... Tolong kembalikan itu padaku!",
  ui_story_5066_50660901_84_dialog_content = "Ck, kau memang tak mau menyerah, ya?",
  ui_story_5066_50660901_85_dialog_content = "Hee-hee, aku sudah siap untuk ini!",
  ui_story_5066_50660901_86_dialog_content = "...",
  ui_story_5066_50660901_87_dialog_content = "Eeek!",
  ui_story_5066_50660901_88_dialog_content = "Saya tidak ingin ada masalah, jadi tolong... tolong minggir...!",
  ui_story_5066_50660901_89_dialog_content = "…!",
  ui_story_5066_50660901_90_dialog_content = "Ah... Aku tidak punya pilihan selain bertarung, tapi aku bersumpah... Aku bersumpah akan mengejar pencuri itu...",
  ui_story_5066_50660902_1_dialog_content = "Hosh… Hosh… Hosh…",
  ui_story_5066_50660902_2_dialog_content = "Meskipun... aku berhasil menghindari para pengawal itu...",
  ui_story_5066_50660902_3_dialog_content = "Sepertinya... pencuri... sudah lama pergi...",
  ui_story_5066_50660902_4_dialog_content = "Aqua Lord... Apakah kamu... masih di sana...?",
  ui_story_5066_50660902_5_dialog_content = "...",
  ui_story_5066_50660902_6_dialog_content = "Boo-hoo... Aku tahu. Tanpa klarinet, kita tidak bisa berkomunikasi satu sama lain.",
  ui_story_5066_50660902_7_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5066_50660902_8_dialog_content = "Hah? ... Ap-Apa itu suara tadi? Jangan bilang...",
  ui_story_5066_50660902_9_dialog_content = "Apakah raja dan pencuri bekerja sama untuk menyerang kita di setiap front...?",
  ui_story_5066_50660902_10_dialog_content = "Aku... Aku mungkin tak bisa menghubungi Aqua Lord lagi, tapi...",
  ui_story_5066_50660902_11_dialog_content = "Aku berjanji bahwa aku tidak akan mundur...",
  ui_story_5066_50660902_12_dialog_content = "Yang Mulia, inilah itu!",
  ui_story_5066_50660902_13_dialog_content = "...",
  ui_story_5066_50660902_14_dialog_content = "Aku tak pernah menyangka pemberontakan akan meletus di kota yang kumuh seperti ini.",
  ui_story_5066_50660902_15_dialog_content = "Akan kuperlihatkan kepada orang-orang pemberontak ini betapa bodohnya mereka!",
  ui_story_5066_50660902_16_dialog_content = "Sekarang aku mengangkat kalian sebagai garda depan! Ikuti aku, dan tunjukkan kekuatan serta kemegahan Kerajaan Merman kita bersama-sama!",
  ui_story_5066_50660902_17_dialog_content = "Ya!!!",
  ui_story_5066_50660902_18_dialog_content = "...",
  ui_story_5066_50660902_19_dialog_content = "Apakah itu... Raja Merman!?",
  ui_story_5066_50660902_20_dialog_content = "Apakah dia benar-benar di sini... untuk membalas dendam demi anaknya...?",
  ui_story_5066_50660902_21_dialog_content = "Cepat! Pergi dan beritahu Queen Connolly!",
  ui_story_5066_50660902_22_dialog_content = "Heh, sekelompok orang yang tak karuan.",
  ui_story_5066_50660902_23_dialog_content = "Semua penduduk rendahan, lihat baik-baik! Saya adalah raja kalian!",
  ui_story_5066_50660902_24_dialog_content = "Saya secara resmi menyatakan Connolly dan pengikutnya sebagai pemberontak.",
  ui_story_5066_50660902_25_dialog_content = "Di sini, aku mencari pembalasan atas aib yang dialami anakku dan pemberontakan penduduk kota!",
  ui_story_5066_50660902_26_dialog_content = "Penjaga, bersiaplah untuk bertempur!",
  ui_story_5066_50660902_27_dialog_content = "Ya!!!",
  ui_story_5066_50661001_1_dialog_content = "...",
  ui_story_5066_50661001_2_dialog_content = "Raja Merman... meskipun dulu Anda menindas kami, sekarang, kami tidak takut lagi padamu!",
  ui_story_5066_50661001_3_dialog_content = "Dengan perlindungan Queen Connolly, kamu sama sekali tidak menjadi ancaman bagi kami!",
  ui_story_5066_50661001_4_dialog_content = "Hahahaha, Queen Connolly? Nama yang sangat konyol!",
  ui_story_5066_50661001_5_dialog_content = "Kamu mungkin tidak takut padaku, tapi aku penasaran apakah kamu takut dengan ini!",
  ui_story_5066_50661001_6_dialog_content = "Apakah itu... meriam?",
  ui_story_5066_50661001_7_dialog_content = "Tong ini sangat besar... tapi untuk Queen Connolly, ini bukan masalah besar!",
  ui_story_5066_50661001_8_dialog_content = "Ya, semua orang, jangan takut; tunggu Queen Connolly untuk mengatasinya!",
  ui_story_5066_50661001_9_dialog_content = "Hosh… Hosh… Hosh…",
  ui_story_5066_50661001_10_dialog_content = "Um... Maaf aku terlambat...",
  ui_story_5066_50661001_11_dialog_content = "Queen Connolly ada di sini!",
  ui_story_5066_50661001_12_dialog_content = "Seperti cara kamu menghempaskan pangeran yang menyebalkan itu, hempaskan juga raja sombong ini!",
  ui_story_5066_50661001_13_dialog_content = "Tabrak dia! Tabrak dia! Tabrak dia!",
  ui_story_5066_50661001_14_dialog_content = "Baiklah…",
  ui_story_5066_50661001_15_dialog_content = "Tentakel-tentakel ini masih bersamaku...",
  ui_story_5066_50661001_16_dialog_content = "Namun…",
  ui_story_5066_50661001_17_dialog_content = "Ini kah ratu yang kalian semua nantikan? Sungguh pemandangan yang menarik, harus kuakui!",
  ui_story_5066_50661001_18_dialog_content = "Siap-siap, garda depan! Tembak!",
  ui_story_5066_50661001_19_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5066_50661001_20_dialog_content = "Urgh... Aku... Aku akan melindungi semua orang!",
  ui_story_5066_50661001_21_dialog_content = "<color=#e8d9bb>Duarr...</color>",
  ui_story_5066_50661001_22_dialog_content = "Ah, tidak seperti itu... Tentakel-tentakel ini tidak mengikuti perintahku...",
  ui_story_5066_50661001_23_dialog_content = "Tidak, tunggu... bukan mereka tidak mengikuti. Mereka hanya tidak bisa memahami aku...",
  ui_story_5066_50661001_24_dialog_content = "Dalam situasi ini...",
  ui_story_5066_50661001_25_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5066_50661001_26_dialog_content = "Eh... bisakah itu karena Queen Connolly tidak bisa menandingi meriam dan pasukan terdepan sang Raja?",
  ui_story_5066_50661001_27_dialog_content = "Dia tampak sedikit aneh. Apakah kita akan kalah...?",
  ui_story_5066_50661001_28_dialog_content = "Cukupkan omongan seperti itu! Tidak mungkin kita akan kalah!",
  ui_story_5066_50661001_29_dialog_content = "Dalam situasi seperti ini... Kita harus membantu dia untuk mendapatkan kembali kekuatan semula...",
  ui_story_5066_50661001_30_dialog_content = "Benar, jadi mari kita berikan perlindungan yang dia butuhkan!",
  ui_story_5066_50661001_31_dialog_content = "Semua orang... Tapi aku...",
  ui_story_5066_50661001_32_dialog_content = "Tanpa klarinetku... Aku tidak sekuat dulu...",
  ui_story_5066_50661001_33_dialog_content = "Tapi tentakel ini... S-Selama mereka masih ada, aku akan terus bertarung...!",
  ui_story_5066_50661102_1_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5066_50661102_2_dialog_content = "Argh…",
  ui_story_5066_50661102_3_dialog_content = "Connolly! Kamu tidak apa-apa?!",
  ui_story_5066_50661102_4_dialog_content = "A... Aku baik-baik saja, hanya saja...",
  ui_story_5066_50661102_5_dialog_content = "Sang Penguasa Air... Kurasa dia tidak bisa bertahan lebih lama lagi...",
  ui_story_5066_50661102_6_dialog_content = "<anim type=Shake>éµè Œâ...</anim>",
  ui_story_5066_50661102_7_dialog_content = "<anim type=Shake>ç·tu€¦... ï|'H>■</anim>",
  ui_story_5066_50661102_8_dialog_content = "Maaf sekali... Tapi sekarang... Aku tidak mengerti satu kata pun yang kamu katakan...",
  ui_story_5066_50661102_9_dialog_content = "<anim type=Shake>ç·tuوˆگم€... â€¦â€■</anim>",
  ui_story_5066_50661102_10_dialog_content = "Hai... lihat Queen Connolly! Dia...",
  ui_story_5066_50661102_11_dialog_content = "Tentakel-tentakel itu... Mereka meredup, menghilang...",
  ui_story_5066_50661102_12_dialog_content = "<size=45>Hahahahaha!</size>",
  ui_story_5066_50661102_13_dialog_content = "Ratu baru yang kalian sebut itu hanyalah seorang boneka belaka!",
  ui_story_5066_50661102_14_dialog_content = "Semuanya, serang! Siapa pun yang bisa menangkap dia akan diberi hadiah yang melimpah!",
  ui_story_5066_50661102_15_dialog_content = "Tahan di sana! Lawanmu ada di sini!",
  ui_story_5066_50661102_16_dialog_content = "Kami tidak akan... Membiarkan kamu mendekati Connolly...",
  ui_story_5066_50661102_17_dialog_content = "Luar biasa! Kau percaya kau bisa menghentikanku?",
  ui_story_5066_50661102_18_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5066_50661102_19_dialog_content = "Argh! Minggir, kalian anjing penjilat yang kotor!",
  ui_story_5066_50661102_20_dialog_content = "Serahkan orang-orang ini padaku, Dayna. Cepatlah pergi ke Connolly...",
  ui_story_5066_50661102_21_dialog_content = "Siap!",
  ui_story_5066_50661102_22_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5066_50661102_23_dialog_content = "<size=33>Boo-hoo... Tidak, aku salah lagi... Aku... Aku sangat minta maaf!</size>",
  ui_story_5066_50661102_24_dialog_content = "Tetap semangat, Connolly!",
  ui_story_5066_50661102_25_dialog_content = "Apakah... Apakah itu kamu, Dayna?",
  ui_story_5066_50661102_26_dialog_content = "Yep! Jangan khawatir, aku akan melindungi pelarianmu.",
  ui_story_5066_50661102_27_dialog_content = "Hah...? Tapi aku tidak bisa meninggalkan semua orang seperti ini...",
  ui_story_5066_50661102_28_dialog_content = "Tidak masalah, jadi serahkan saja ini pada kami untuk saat ini.",
  ui_story_5066_50661102_29_dialog_content = "Memang benar bahwa saat ini kami tidak tahu bagaimana cara membantu kamu.",
  ui_story_5066_50661102_30_dialog_content = "Tapi kamu akan kembali setelah kekuatanmu pulih, kan?",
  ui_story_5066_50661102_31_dialog_content = "Aku…",
  ui_story_5066_50661102_32_dialog_content = "Kita ngobrol nanti, sekarang pergi!",
  ui_story_5066_50661102_33_dialog_content = "Hiks... Baiklah, aku akan menurutimu.",
  ui_story_5066_50661102_34_dialog_content = "<size=33><color=#e8d9bb>Duar—!</color></size>",
  ui_story_5066_50661102_35_dialog_content = "Mereka masih bertarung...",
  ui_story_5066_50661102_36_dialog_content = "Semuanya begitu menakutkan... sniff... Aku memang lebih baik berada di tempat gelap seperti ini.",
  ui_story_5066_50661102_37_dialog_content = "Selama aku bersembunyi di parit gelap dan kosong ini, semuanya akan baik-baik saja...",
  ui_story_5066_50661102_38_dialog_content = "Semuanya akan baik-baik saja... Benar?",
  ui_story_5066_50661102_39_dialog_content = "Akhirnya... Aku bisa tidur nyenyak... Benar?",
  ui_story_5066_50661201_1_dialog_content = "<size=45><color=#e8d9bb>Duar—!</color></size>",
  ui_story_5066_50661201_2_dialog_content = "Huu-huu...",
  ui_story_5066_50661201_3_dialog_content = "Aku... aku seharusnya membantu yang lain...",
  ui_story_5066_50661201_4_dialog_content = "Tapi tubuhku... Tidak bisa berhenti gemetar...",
  ui_story_5066_50661201_5_dialog_content = "Lagi pula, aku tidak bisa mengendalikan tentakel ini... Tidak dalam kondisi seperti sekarang...",
  ui_story_5066_50661201_6_dialog_content = "Bahkan jika saya kembali, saya hanya akan mengganggu semua orang...",
  ui_story_5066_50661201_7_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_5066_50661201_8_dialog_content = "Wow... Sangat hangat... Apakah ini arus air hangat?",
  ui_story_5066_50661201_9_dialog_content = "<color=#e8d9bb>Pat—</color>",
  ui_story_5066_50661201_10_dialog_content = "Hmm? Pundakku...?",
  ui_story_5066_50661201_11_dialog_content = "Eeek! A-Apakah ada yang menemukanku...? Tapi siapapun itu, sepertinya mereka tidak bermusuhan...",
  ui_story_5066_50661201_12_dialog_content = "Siapa... Siapa yang bisa menemukanku di sini dan saat ini dari semua tempat...?",
  ui_story_5066_50661201_13_dialog_content = "Halo, Connolly.",
  ui_story_5066_50661201_14_dialog_content = "Wow... Lumba-lumba putih yang cantik! Dan matanya... Begitu hangat dan terang...",
  ui_story_5066_50661201_15_dialog_content = "Siapa kamu?",
  ui_story_5066_50661201_16_dialog_content = "Tidak perlu takut, Connolly. Aku salah satu dari orang-orang bawah laut yang kamu dan Aqua Lord bantu.",
  ui_story_5066_50661201_17_dialog_content = "Oh... Benarkah? Tapi sepertinya aku tidak ingat...",
  ui_story_5066_50661201_18_dialog_content = "Aku mengerti. Dengan begitu banyak orang yang telah kamu bantu, mustahil untuk mengingat mereka semua.",
  ui_story_5066_50661201_19_dialog_content = "Aku tahu... tapi tetap saja...",
  ui_story_5066_50661201_20_dialog_content = "<size=33>Aku rasa aku tak bisa melupakan lumba-lumba putih yang baik hati dan cantik ini begitu saja...</size>",
  ui_story_5066_50661201_21_dialog_content = "Tapi sepertinya kamu sedang mengalami sedikit masalah sekarang.",
  ui_story_5066_50661201_22_dialog_content = "Dan sekarang giliran saya untuk membantu Anda sebanyak yang saya bisa.",
  ui_story_5066_50661201_23_dialog_content = "A... hiks... Kamu memang benar...",
  ui_story_5066_50661201_24_dialog_content = "Tapi bagaimana mungkin... aku bisa menyusahkanmu dengan masalahku?",
  ui_story_5066_50661201_25_dialog_content = "Mengapa itu akan menjadi masalah? Terinspirasi oleh Anda dan bagaimana Anda menikmati membantu orang lain, kini saya telah mengumpulkan keberanian untuk membantu.",
  ui_story_5066_50661201_26_dialog_content = "Selain itu, dunia bawah air adalah rumah bersama kita, jadi saya ingin berkontribusi dalam melindunginya.",
  ui_story_5066_50661201_27_dialog_content = "Oh... Begitukah...?",
  ui_story_5066_50661201_28_dialog_content = "Nah, pertama-tama, kita harus keluar dari sini.",
  ui_story_5066_50661201_29_dialog_content = "Tempat ini tidak cocok untukmu dalam keadaanmu saat ini.",
  ui_story_5066_50661201_30_dialog_content = "Aku... Aku tahu, tapi sekarang aku harus ke mana?",
  ui_story_5066_50661201_31_dialog_content = "Aku tahu tempat perlindungan yang aman. Maukah kamu ikut denganku?",
  ui_story_5066_50661201_32_dialog_content = "Ya... Jika kamu tidak keberatan...",
  ui_story_5066_50661201_33_dialog_content = "Tolong... bawa aku bersamamu...",
  ui_story_5066_50661201_34_dialog_content = "... Tunggu.",
  ui_story_5066_50661201_35_dialog_content = "Ada apa?",
  ui_story_5066_50661201_36_dialog_content = "Apakah akan ada orang lain di sana juga...?",
  ui_story_5066_50661201_37_dialog_content = "Ya, tentu saja. Bagaimanapun, semua orang sangat menyukai tempat itu.",
  ui_story_5066_50661201_38_dialog_content = "Oh...",
  ui_story_5066_50661201_39_dialog_content = "Dayna dan yang lainnya masih bertarung...",
  ui_story_5066_50661201_40_dialog_content = "Tapi saya... Saya tidak tahu bagaimana cara membantu mereka...",
  ui_story_5066_50661201_41_dialog_content = "Apakah orang-orang di sana... akan membenci saya karena itu?",
  ui_story_5066_50661201_42_dialog_content = "Tidak perlu terlalu khawatir.",
  ui_story_5066_50661201_43_dialog_content = "Mungkin kamu bisa merasa lebih percaya diri tentang reputasi yang telah kamu bangun saat membantu para penduduk di masa lalu.",
  ui_story_5066_50661201_44_dialog_content = "Lebih... percaya diri?",
  ui_story_5066_50661201_45_dialog_content = "Tapi aku bukan lagi ratu yang mereka percayai... Aku hanya seorang pelarian yang memalukan sekarang...",
  ui_story_5066_50661201_46_dialog_content = "Belum terlambat.",
  ui_story_5066_50661201_47_dialog_content = "Kamu hanya mundur selangkah untuk saat ini, dan semua orang benar-benar bisa merasakannya.",
  ui_story_5066_50661201_48_dialog_content = "Bukankah dulu kamu selalu membantu mereka, memperlakukan urusan para penghuni bawah laut seperti urusanmu sendiri?",
  ui_story_5066_50661201_49_dialog_content = "Sekarang giliran Anda untuk mencari bantuan mereka.",
  ui_story_5066_50661201_50_dialog_content = "Apakah... aku benar-benar layak untuk melakukan itu?",
  ui_story_5066_50661201_51_dialog_content = "Tentu saja, karena kebaikan hatimu, Dayna, Robyn, dan semua orang berkumpul di sekitarmu.",
  ui_story_5066_50661201_52_dialog_content = "Kebijaksanaan mereka pasti akan membantu dalam menyelesaikan masalah Anda.",
  ui_story_5066_50661201_53_dialog_content = "Pengetahuan yang dikombinasikan semua orang... sepertinya memang begitu...",
  ui_story_5066_50661201_54_dialog_content = "Meskipun saya tidak tahu harus berbuat apa, mungkin salah satu dari mereka... akan memiliki jawabannya?",
  ui_story_5066_50661201_55_dialog_content = "Percayalah pada semua orang, dan pada diri sendiri.",
  ui_story_5066_50661201_56_dialog_content = "Semua yang telah kamu lakukan sebelum ini tidak akan sia-sia.",
  ui_story_5066_50661201_57_dialog_content = "Jangan lupa, kamu masih harus memenuhi keinginan monster kuno itu, kan?",
  ui_story_5066_50661201_58_dialog_content = "Ah!",
  ui_story_5066_50661201_59_dialog_content = "Benar... Aqua Lord... Aku sangat minta maaf telah mempermalukan Anda seperti ini...",
  ui_story_5066_50661201_60_dialog_content = "Tapi sekarang aku tahu... Aku harus pergi meminta wawasan dari semua orang!",
  ui_story_5066_50661301_1_dialog_content = "<color=#e8d9bb>Bergemerincing, bergemerincing, bergemerincing—</color>",
  ui_story_5066_50661301_2_dialog_content = "Wow... Aku tidak tahu ada tempat seperti ini di sini...",
  ui_story_5066_50661301_3_dialog_content = "Hangat dan tenang sekali... Rasanya seperti di rumah.",
  ui_story_5066_50661301_4_dialog_content = "Tempat ini cukup indah, bukan?",
  ui_story_5066_50661301_5_dialog_content = "Iya. Terima kasih banyak sudah mengajakku ke sini...",
  ui_story_5066_50661301_6_dialog_content = "Oh... Astaga! Hampir saja aku ingin tinggal di sini dan menghindari masalahku...",
  ui_story_5066_50661301_7_dialog_content = "Meskipun sangat menyenangkan... Aku tahu aku tidak bisa bersembunyi di sini selamanya.",
  ui_story_5066_50661301_8_dialog_content = "Jadi, sudahkah kamu menemukan masalah apa yang ingin kamu minta bantuan dari semua orang?",
  ui_story_5066_50661301_9_dialog_content = "Ah... baru saja aku sadari... ternyata ada begitu banyak orang di sini...",
  ui_story_5066_50661301_10_dialog_content = "Hai, bukankah ini Connolly?",
  ui_story_5066_50661301_11_dialog_content = "Kami berhasil mendapatkan kembali terumbu karang keluarga kami dari Mermen, semua berkat kamu!",
  ui_story_5066_50661301_12_dialog_content = "Anak-anak kami sangat menyukaimu! Kapan waktu yang tepat bagi kamu untuk memberi mereka pelajaran musik lagi?",
  ui_story_5066_50661301_13_dialog_content = "Apakah ini... benar-benar cara semua orang melihatku...?",
  ui_story_5066_50661301_14_dialog_content = "Benar, kebaikan menarik orang untuk bersama-sama.",
  ui_story_5066_50661301_15_dialog_content = "Jadi itulah mengapa aku harus... percaya pada niat baik semua orang juga...",
  ui_story_5066_50661301_16_dialog_content = "A... Aku paham sekarang!",
  ui_story_5066_50661301_17_dialog_content = "Um... Bolehkah saya merepotkan kalian semua hanya beberapa menit dari waktu kalian?",
  ui_story_5066_50661301_18_dialog_content = "Silakan. Kami bisa melihat bahwa sepertinya kamu mengalami beberapa masalah.",
  ui_story_5066_50661301_19_dialog_content = "Jangan ragu untuk memberi tahu kami jika ada yang bisa kami bantu!",
  ui_story_5066_50661301_20_dialog_content = "Dan jika masih ada lagi...",
  ui_story_5066_50661301_21_dialog_content = "Huhu, aku tidak menyadari bahwa semua orang akan begitu bersedia untuk membantu...",
  ui_story_5066_50661301_22_dialog_content = "Ehem. Yah, teman-teman, saya sangat menghargai antusiasme kalian.",
  ui_story_5066_50661301_23_dialog_content = "Tapi tolong, satu per satu, jika tidak Connolly tidak akan bisa mendengar siapa pun.",
  ui_story_5066_50661301_24_dialog_content = "Oh... Terima kasih, White Dolphin.",
  ui_story_5066_50661301_25_dialog_content = "<size=33>Tanpa kamu... Aku tidak tahu apa yang akan kulakukan...</size>",
  ui_story_5066_50661301_26_dialog_content = "Saya... Anu, ingin meminta wawasan dari semua orang mengenai suatu masalah...",
  ui_story_5066_50661301_27_dialog_content = "Beberapa waktu lalu... Seorang pencuri jahat mencuri klarinetku, dan akhirnya aku kehilangan kemampuanku untuk berkomunikasi dengan Aqua Lord...",
  ui_story_5066_50661301_28_dialog_content = "Apakah ada yang punya ide... tentang bagaimana saya bisa mengembalikan koneksi saya dengan Aqua Lord?",
  ui_story_5066_50661301_29_dialog_content = "...",
  ui_story_5066_50661301_30_dialog_content = "A-aku punya saran!",
  ui_story_5066_50661301_31_dialog_content = "Silakan, lanjutkan.",
  ui_story_5066_50661301_32_dialog_content = "Dalam kisah legendaris yang saya dengar saat masih muda, kekuatan Aqua Lord sangat erat kaitannya dengan kuil!",
  ui_story_5066_50661301_33_dialog_content = "Ini harus menjadi petunjuk penting! Selain itu, Connolly, bukankah kamu menyebutkan tentang candi sebelumnya?",
  ui_story_5066_50661301_34_dialog_content = "Jika kamu bisa menemukan candi kuno ini, pasti kekuatanmu akan kembali!",
  ui_story_5066_50661301_35_dialog_content = "Connolly, apa pendapatmu tentang ini?",
  ui_story_5066_50661301_36_dialog_content = "Kurasa... Pendapatmu ada benarnya...",
  ui_story_5066_50661301_37_dialog_content = "Tapi, mungkin aku akan kembali terlambat jika aku mencari kuil kuno itu sekarang. Juga...",
  ui_story_5066_50661301_38_dialog_content = "Aqua Lord mempercayai saya untuk membangun kuil baru, tetapi setelah kami bekerja keras membangunnya... Raja Merman merebutnya untuk dirinya sendiri.",
  ui_story_5066_50661301_39_dialog_content = "Is... Ini semua salahku...",
  ui_story_5066_50661301_40_dialog_content = "Tetap berharap, Connolly. Lihat? Para penduduk sudah punya ide baru!",
  ui_story_5066_50661301_41_dialog_content = "Hah...? Baiklah... Tolong bagikan pendapatmu denganku!",
  ui_story_5066_50661301_42_dialog_content = "Saya percaya bahwa klarinet hanyalah salah satu jenis instrumen musik.",
  ui_story_5066_50661301_43_dialog_content = "Karena tidak ada klarinet, bisakah kita menggunakan instrumen lain sebagai gantinya?",
  ui_story_5066_50661301_44_dialog_content = "Mungkin Aqua Lord tidak terlalu pemilih tentang timbre, tahu?",
  ui_story_5066_50661301_45_dialog_content = "Tidak... Pemilih?",
  ui_story_5066_50661301_46_dialog_content = "Ada yang terlintas di pikiran?",
  ui_story_5066_50661301_47_dialog_content = "Tapi... Selama ini, saya percaya bahwa kekuatannya ada dalam instrumen yang ditinggalkan ibu saya...",
  ui_story_5066_50661301_48_dialog_content = "Apakah benar-benar mungkin untuk berkomunikasi dengan Aqua Lord tanpa klarinetnya...?",
  ui_story_5066_50661301_49_dialog_content = "Aku percaya itu mungkin.",
  ui_story_5066_50661301_50_dialog_content = "Hah...?!",
  ui_story_5066_50661301_51_dialog_content = "Saya pikir kemampuan untuk berkomunikasi dengan Aqua Lord mungkin merupakan kekuatan bawaan Anda sendiri.",
  ui_story_5066_50661301_52_dialog_content = "Kekuatan milikku sendiri...? Tapi... Bagaimana bisa...?",
  ui_story_5066_50661301_53_dialog_content = "Tapi pikirkanlah: sebelum membuat pact, bukankah kamu sudah memiliki kemampuan untuk berkomunikasi dengan Aqua Lord melalui musik?",
  ui_story_5066_50661301_54_dialog_content = "Lagipula, bahkan tanpa klarinet, tentakel-tentakel itu tidak menghilang; mereka hanya kurang responsif.",
  ui_story_5066_50661301_55_dialog_content = "Jadi mungkin bukan hanya tentang klarinet saja; yang benar-benar penting bisa jadi adalah musikmu, bukan?",
  ui_story_5066_50661301_56_dialog_content = "Musik... saya?",
  ui_story_5066_50661301_57_dialog_content = "Benar. Cobalah untuk merenungkan pertempuran-pertempuran di masa lalu Anda.",
  ui_story_5066_50661301_58_dialog_content = "Dan pikirkan apa yang sebenarnya memberi Anda kekuatan...",
  ui_story_5066_50661302_1_dialog_content = "*memainkan lagu*",
  ui_story_5066_50661302_2_dialog_content = "<color=#e8d9bb>Plak—Plak!</color>",
  ui_story_5066_50661302_3_dialog_content = "...",
  ui_story_5066_50661302_4_dialog_content = "*memainkan lagu*",
  ui_story_5066_50661302_5_dialog_content = "<color=#e8d9bb>Plak—Plak!</color>",
  ui_story_5066_50661302_6_dialog_content = "Eek...!",
  ui_story_5066_50661302_7_dialog_content = "...",
  ui_story_5066_50661302_8_dialog_content = "Aku... aku ingat sekarang...",
  ui_story_5066_50661302_9_dialog_content = "Ibu pernah bilang bahwa kekuatan musik bukan pada instrumennya, melainkan pada musik itu sendiri...",
  ui_story_5066_50661302_10_dialog_content = "Saya sangat sibuk menghargai klarinet yang ditinggalkannya untuk saya sehingga saya melupakan semua yang dia ajarkan kepada saya...",
  ui_story_5066_50661302_11_dialog_content = "Tapi sekarang kamu sudah ingat, bukan?",
  ui_story_5066_50661302_12_dialog_content = "Ya. Jadi sekarang... Jika aku bisa menemukan potongan musik yang tepat, mungkin aku bisa memanggil Aqua Lord lagi...",
  ui_story_5066_50661302_13_dialog_content = "Seperti... saat pertama kali aku memanggilnya di loteng.",
  ui_story_5066_50661302_14_dialog_content = "Masih ingat not balok yang kamu mainkan dulu?",
  ui_story_5066_50661302_15_dialog_content = "Iya... Namanya \"The Shape of Water\"...",
  ui_story_5066_50661302_16_dialog_content = "Namun…",
  ui_story_5066_50661302_17_dialog_content = "Apa, kamu tidak bisa memainkan kertas musik itu lagi?",
  ui_story_5066_50661302_18_dialog_content = "Ya... partitur musik itu masih ada di loteng bibiku...",
  ui_story_5066_50661302_19_dialog_content = "Tapi saat ini... Seluruh kota berada di bawah kendali Raja Merman.",
  ui_story_5066_50661302_20_dialog_content = "Aku hanya memainkannya beberapa kali, dan lagu ini sangat kompleks...",
  ui_story_5066_50661302_21_dialog_content = "Yang kemungkinan besar berarti... aku tidak akan bisa memanggil Aqua Lord...",
  ui_story_5066_50661302_22_dialog_content = "Jangan terlalu stres. Kita masih punya banyak pilihan.",
  ui_story_5066_50661302_23_dialog_content = "Kamu juga bisa memikirkan apakah ada komposisi yang mungkin menarik minat Aqua Lord?",
  ui_story_5066_50661302_24_dialog_content = "Ah... Ada! Ini lagu yang berjudul <color=#FFB400>Rumah</color>!",
  ui_story_5066_50661302_25_dialog_content = "Rumah?",
  ui_story_5066_50661302_26_dialog_content = "Ya! Ini lagu yang indah... Salah satu yang diajarkan ibuku.",
  ui_story_5066_50661302_27_dialog_content = "Ini juga lagu yang aku mainkan... Ketika aku dan Aqua Lord akhirnya mulai saling memahami!",
  ui_story_5066_50661302_28_dialog_content = "Aku rasa ini dia! Lagu ini harus berhasil!",
  ui_story_5066_50661302_29_dialog_content = "Hmm... Kurasa begitu, tapi...",
  ui_story_5066_50661302_30_dialog_content = "A-Aku tidak bisa berjanji, jadi... bisakah kamu menemani aku ke kuil... dan membantu aku memanggil Aqua Lord?",
  ui_story_5066_50661302_31_dialog_content = "Tenang saja, aku akan tepat di sampingmu.",
  ui_story_5066_50661302_32_dialog_content = "Lagi pula, semua orang di sana masih menunggumu.",
  ui_story_5066_50661302_33_dialog_content = "Tunggu aku, semuanya...",
  ui_story_5066_50661302_34_dialog_content = "Ini untuk kalian semua...",
  ui_story_5066_50661302_35_dialog_content = "Jika aku tidak memiliki klarinet, aku akan menggunakan instrumen lain. Jika aku tidak bisa memainkan The Shape of Water, maka aku akan mencari lagu lain untuk dimainkan. Apapun itu... Aku pasti...",
  ui_story_5066_50661302_36_dialog_content = "Saya pasti akan berkomunikasi dengan Aqua Lord lagi!",
  ui_story_5066_50661401_1_dialog_content = "Huff... Huff... Akhirnya kita semakin dekat...",
  ui_story_5066_50661401_2_dialog_content = "Terima kasih telah bersamaku selama ini, White Dolphin... Jika bukan karena kamu...",
  ui_story_5066_50661401_3_dialog_content = "Ini semua adalah kekuatanmu sendiri; peran saya sangat tidak signifikan.",
  ui_story_5066_50661401_4_dialog_content = "Dan saat yang membutuhkanmu untuk menunjukkan kekuatan sejatimu belum tiba.",
  ui_story_5066_50661401_5_dialog_content = "Oh... T-Tapi kamu akan selalu ada untuk membantuku, 'kan?",
  ui_story_5066_50661401_6_dialog_content = "Tentu saja, aku akan bersamamu di setiap langkah yang kamu jalani.",
  ui_story_5066_50661401_7_dialog_content = "Yo, mari kita lihat siapa gadis kecil berantakan ini?",
  ui_story_5066_50661401_8_dialog_content = "Hah...? Bukankah kau...?",
  ui_story_5066_50661401_9_dialog_content = "Astaga, bukankah ini Queen Connolly? Sudah lama tidak bertemu, dan kamu sudah jadi berantakan seperti ini?",
  ui_story_5066_50661401_10_dialog_content = "Sepupu...?",
  ui_story_5066_50661401_11_dialog_content = "Sedang apa kau di sini?",
  ui_story_5066_50661401_12_dialog_content = "Debut yang luar biasa, 'kan? Iri, 'kan? Ini adalah hadiah dari Raja Merman sendiri!",
  ui_story_5066_50661401_13_dialog_content = "Tenslotte, aku adalah pahlawan terbesar dalam pertempuran ini; sekarang aku cukup dihormati di depan Raja Merman!",
  ui_story_5066_50661401_14_dialog_content = "Dan kamu, sepupuku yang malang dan tak berguna... andai saja kau mendengarkanku saat itu dan menjadi koleksi Pangeran Merman.",
  ui_story_5066_50661401_15_dialog_content = "Kamu nggak akan pernah berakhir dalam situasi yang menyedihkan seperti ini! Hahaha...",
  ui_story_5066_50661401_16_dialog_content = "Kontributor terbesar...?",
  ui_story_5066_50661401_17_dialog_content = "(Tapi... Sepupuku tidak pernah punya bakat yang benar-benar istimewa! Bagaimana dia bisa menjadi \"kontributor terbesar\" dalam kampanye raja...?)",
  ui_story_5066_50661401_18_dialog_content = "(Jangan-jangan?!)",
  ui_story_5066_50661401_19_dialog_content = "Kamu... Kamu yang mencuri klarinetku, 'kan?!",
  ui_story_5066_50661401_20_dialog_content = "Oh... Jadi kamu baru menyadarinya sekarang? Bukankah itu sedikit terlambat dan terlalu bodoh, saudara sepupuku yang terkasih?",
  ui_story_5066_50661401_21_dialog_content = "Tapi meskipun kamu telah menyadarinya, apa yang bisa kamu lakukan sekarang?",
  ui_story_5066_50661401_22_dialog_content = "Apakah kamu punya cara untuk membalas dendam padaku? Aku ragu!",
  ui_story_5066_50661401_23_dialog_content = "Tolong... Kembalikan padaku...",
  ui_story_5066_50661401_24_dialog_content = "Apa katamu? Kamu...",
  ui_story_5066_50661401_25_dialog_content = "Aku bilang tolong kembalikan klarinetku...!",
  ui_story_5066_50661401_26_dialog_content = "Hanya kata-kata kosong...",
  ui_story_5066_50661401_27_dialog_content = "Saya sangat sadar, tanpa klarinet itu, kamu sama sekali tidak berguna!",
  ui_story_5066_50661401_28_dialog_content = "Saya...? Memang benar, tidak ada yang istimewa tentang saya...",
  ui_story_5066_50661401_29_dialog_content = "Tapi kekuatan sejati... terletak pada musik!",
  ui_story_5066_50661401_30_dialog_content = "Kekuatan... Lucu sekali...",
  ui_story_5066_50661401_31_dialog_content = "Bahkan tanpa klarinetku, aku bisa menggunakan suaraku...",
  ui_story_5066_50661401_32_dialog_content = "Dan bahkan tanpa partitur musikku... Melodi dan emosi mereka telah terukir di hatiku sejak dulu.",
  ui_story_5066_50661401_33_dialog_content = "Sekarang, yang harus aku lakukan adalah bernyanyi!",
  ui_story_5066_50661401_34_dialog_content = "*bernyanyi*",
  ui_story_5066_50661401_35_dialog_content = "<color=#e8d9bb>Seperti seorang putri yang kembali ke istananya, Connolly bernyanyi saat menaiki tangga berliku, menggunakan suaranya untuk memanggil Aqua Lord...</color>",
  ui_story_5066_50661401_36_dialog_content = "<color=#e8d9bb>Di saat yang bersamaan, dia akhirnya mengungkapkan perasaan yang selama ini terpendam di hatinya.</color>",
  ui_story_5066_50661401_37_dialog_content = "Diam! Berhenti menyanyi... Berhenti! Jauhi aku!",
  ui_story_5066_50661401_38_dialog_content = "Hanya tempat di mana semua orang berkumpul yang bisa disebut rumah!♪",
  ui_story_5066_50661401_39_dialog_content = "Sebuah kastil kosong, tak peduli seberapa megah, akan selalu terasa sepi!♪",
  ui_story_5066_50661401_40_dialog_content = "Jadi tolong dengarkan panggilanku dan kembali ke sisiku!♪",
  ui_story_5066_50661401_41_dialog_content = "Karena di sini adalah rumahmu, di mana kamu tak perlu bersembunyi!♪",
  ui_story_5066_50661401_42_dialog_content = "<color=#e8d9bb>Ketika suaranya bergema, berbagai ikan dan partikel Lumina mulai berkumpul di sekitar Connolly, seolah-olah bergabung dengannya dalam berdoa untuk sebuah keajaiban...</color>",
  ui_story_5066_50661401_43_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5066_50661401_44_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5066_50661401_45_dialog_content = "...",
  ui_story_5066_50661401_46_dialog_content = "Aqua Lord... Aku sangat senang bisa bertemu denganmu lagi...",
  ui_story_5066_50661401_47_dialog_content = "...",
  ui_story_5066_50661401_48_dialog_content = "Maaf... Aku merusak semuanya...",
  ui_story_5066_50661401_49_dialog_content = "Kamu pasti sangat kecewa... telah membuat perjanjian dengan seseorang yang memalukan dan tidak berguna seperti saya... benar?",
  ui_story_5066_50661401_50_dialog_content = "Mungkin aku tak berhak lagi mengatakan bahwa kita terikat... Dan mungkin memang tak pantas bagiku untuk meminta... Tapi aku akan melakukannya juga!",
  ui_story_5066_50661401_51_dialog_content = "Sekarang... Aku benar-benar, sangat butuh bantuanmu!",
  ui_story_5066_50661401_52_dialog_content = "Jadi, bisakah kamu tolong... pinjamkan kekuatanmu satu kali lagi?!",
  ui_story_5066_50661401_53_dialog_content = "...",
  ui_story_5066_50661401_54_dialog_content = "Aku tidak membenci sikapmu saat ini.",
  ui_story_5066_50661401_55_dialog_content = "Kecelakaan ini tidak sepenuhnya salahmu.",
  ui_story_5066_50661401_56_dialog_content = "Setidaknya niat baikmu telah sampai padaku.",
  ui_story_5066_50661401_57_dialog_content = "Lalu, apakah itu berarti...?!",
  ui_story_5066_50661401_58_dialog_content = "Tapi sekarang... Aku tidak bisa membantumu...",
  ui_story_5066_50661401_59_dialog_content = "Oh... Sudah kuduga... tapi aku paham...",
  ui_story_5066_50661401_60_dialog_content = "Jangan salah paham.",
  ui_story_5066_50661401_61_dialog_content = "Sang medium hilang, dan perjanjian itu putus secara prematur. Aku telah kehilangan bentuk fisikku di dunia ini.",
  ui_story_5066_50661401_62_dialog_content = "Sekarang, jika kamu ingin mendapatkan kekuatanku, kamu harus pergi ke kuil...",
  ui_story_5066_50661401_63_dialog_content = "Nah, untuk lebih tepatnya, kamu harus pergi ke kastil mewah yang telah kamu bangun untukku dan mengambil semua kekuatan yang tersisa.",
  ui_story_5066_50661401_64_dialog_content = "Namun…",
  ui_story_5066_50661401_65_dialog_content = "Um... Apakah ada semacam tangkapannya...?",
  ui_story_5066_50661401_66_dialog_content = "Namun, jika kamu ingin memaksimalkan kekuatan tersebut, kamu harus mewarisi kuil dan menjadi Aqua Queen yang sejati.",
  ui_story_5066_50661401_67_dialog_content = "Yang sebenarnya... Aqua Queen...?",
  ui_story_5066_50661401_68_dialog_content = "Apakah Anda mengatakan... Bahwa saat ini saya hanyalah seorang peniru?",
  ui_story_5066_50661401_69_dialog_content = "Kamu bukanlah seorang penipu. Intinya, jika kamu hanya ingin melindungi diri sendiri, kamu sudah cukup jauh.",
  ui_story_5066_50661401_70_dialog_content = "Kehadiran sisaku sudah cukup untuk melindungimu.",
  ui_story_5066_50661401_71_dialog_content = "Namun, jika tujuanmu melindungi kota, keberadaan sisa ku jauh di bawah kekuatan yang dibutuhkan.",
  ui_story_5066_50661401_72_dialog_content = "Kamu harus menerima lebih banyak kekuatan dan... memikul lebih banyak tanggung jawab.",
  ui_story_5066_50661401_73_dialog_content = "Kau harus melangkah maju, dari bayangan menuju sorotan, ke dalam kegelapan di mana bahkan kekuatanku tak bisa melindungimu...",
  ui_story_5066_50661401_74_dialog_content = "Ehehehe...",
  ui_story_5066_50661401_75_dialog_content = "Apa? Apakah kata-kataku terdengar lucu?",
  ui_story_5066_50661401_76_dialog_content = "Hanya saja, untuk pertama kalinya... Kamu terlihat agak bodoh...",
  ui_story_5066_50661401_77_dialog_content = "Kenapa kamu bilang begitu...?",
  ui_story_5066_50661401_78_dialog_content = "Bukankah perasaan saya sudah sangat jelas dalam lagu yang baru saja saya nyanyikan? Dan juga...",
  ui_story_5066_50661401_79_dialog_content = "Kini Lumba-lumba Putih membantu saya, bersama dengan semua orang lain...",
  ui_story_5066_50661401_80_dialog_content = "Tentu saja aku akan memilih untuk terus melanjutkan.",
  ui_story_5066_50661401_81_dialog_content = "Sepertinya kali ini aku mungkin telah meremehkanmu...",
  ui_story_5066_50661401_82_dialog_content = "Lalu, tunjukkan padaku kekuatan tekadmu.",
  ui_story_5066_50661401_83_dialog_content = "Aku akan... Dan aku berjanji tidak akan mengecewakanmu lagi...",
  ui_story_5066_50661401_84_dialog_content = "Sekarang, sepupu terkasih... Bisakah kamu mengembalikan klarinetku?",
  ui_story_5066_50661401_85_dialog_content = "Atau... apakah kamu lebih memilih merasakan kekuatan penuh kemarahanku atas apa yang telah kamu lakukan...?",
  ui_story_5066_50661401_86_dialog_content = "Cih...",
  ui_story_5066_50661401_87_dialog_content = "(Kekuatannya belum sepenuhnya pulih. Selama saya bisa menghentikannya di sini, dia akan tetap menjadi gadis biasa!)",
  ui_story_5066_50661401_88_dialog_content = "Heh, ayo, sepupu...",
  ui_story_5066_50661401_89_dialog_content = "Melayani Raja Ikan, kekuatan saya telah ditingkatkan jauh lebih banyak daripada yang bisa kamu bayangkan.",
  ui_story_5066_50661401_90_dialog_content = "Dan kali ini, aku akan habis-habisan, habis-habisan yang akan mengakhiri hidup sengsaramu! Ayo maju!",
  ui_story_5066_50661402_1_dialog_content = "<color=#e8d9bb>Plak—Plak!</color>",
  ui_story_5066_50661402_2_dialog_content = "*bernyanyi*",
  ui_story_5066_50661402_3_dialog_content = "Aghhh! Aduh aduh... Cukup! Connolly, berhenti. Aku sepupumu!",
  ui_story_5066_50661402_4_dialog_content = "Klarinet, katamu? Baiklah, aku... aku akan mengembalikannya padamu...",
  ui_story_5066_50661402_5_dialog_content = "Kumohon... tolong jangan bunuh aku! Aku memohon padamu...",
  ui_story_5066_50661402_6_dialog_content = "Kamu tidak akan melakukan sesuatu yang kejam dan tidak adil, bukan? Tante dan pamanmu akan hancur, tahu kan, hancur!",
  ui_story_5066_50661402_7_dialog_content = "Benar, mereka masih menunggu kamu pulang ke rumah!",
  ui_story_5066_50661402_8_dialog_content = "Rumah...",
  ui_story_5066_50661402_9_dialog_content = "Tepat sekali, rumah, rumah kita! Ayo, mari kita pulang ke rumah bersama keluarga, orang-orang yang benar-benar mencintai kamu!",
  ui_story_5066_50661402_10_dialog_content = "...",
  ui_story_5066_50661402_11_dialog_content = "Meskipun aku bersyukur kepada bibi dan paman yang telah menampungku setelah aku kehilangan segalanya...",
  ui_story_5066_50661402_12_dialog_content = "Tempat itu bukan lagi rumahku...",
  ui_story_5066_50661402_13_dialog_content = "Lagipula, kau lah yang ingin membawa aku pergi dari rumah mereka... Bukan begitu, sepupu?!",
  ui_story_5066_50661402_14_dialog_content = "Dan sekarang kamu ingin menghancurkan rumah orang-orang ini juga... Jangan salah paham, kamu adalah musuhku sekarang.",
  ui_story_5066_50661402_15_dialog_content = "Aduh! Tidak... ini hanya kesalahpahaman besar, kamu... tolong jangan bunuh aku!!",
  ui_story_5066_50661402_16_dialog_content = "Aku... Aku tidak akan pernah membunuh siapa pun... Kamu dan aku tidak sama...",
  ui_story_5066_50661402_17_dialog_content = "Jadi pergi... tinggalkan kota ini sekarang juga... Dan jangan pernah kembali!",
  ui_story_5066_50661402_18_dialog_content = "Baiklah, aku mengerti. Biarkan aku pergi; aku takkan kembali, dan kamu takkan melihatku lagi...",
  ui_story_5066_50661402_19_dialog_content = "...",
  ui_story_5066_50661402_20_dialog_content = "Aku seharusnya tidak mengganggu sepupuku sekarang...",
  ui_story_5066_50661402_21_dialog_content = "Raja Merman sudah menguasai sebagian besar area ini. Tidak hanya itu...",
  ui_story_5066_50661402_22_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5066_50661402_23_dialog_content = "Suara tembakan meriam semakin dekat. Bahkan, sepertinya suara itu langsung mengarah kepadaku...",
  ui_story_5066_50661402_24_dialog_content = "Tapi kali ini aku sudah siap menghadapinya!",
  ui_story_5066_50661402_25_dialog_content = "Dayna, Robyn, semua orang... Tolong jaga keselamatan!",
  ui_story_5066_50661501_1_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5066_50661501_2_dialog_content = "Argh! Jangan bilang kita harus menyerah posisi ini juga?!",
  ui_story_5066_50661501_3_dialog_content = "Tidak ada habisnya semua pengawal Merman yang bau ini!",
  ui_story_5066_50661501_4_dialog_content = "Dayna... Kita harus mundur untuk saat ini...",
  ui_story_5066_50661501_5_dialog_content = "Tetapi jika kita mundur sekarang, hanya akan membuat Connolly semakin dalam bahaya!",
  ui_story_5066_50661501_6_dialog_content = "Kamu bisa terus melanjutkan, bukan Robyn?",
  ui_story_5066_50661501_7_dialog_content = "Jika untuk Connolly... Saya bisa bertahan sedikit lebih lama.",
  ui_story_5066_50661501_8_dialog_content = "<color=#e8d9bb>Plak—Plak!</color>",
  ui_story_5066_50661501_9_dialog_content = "Apakah itu... tentakel?!",
  ui_story_5066_50661501_10_dialog_content = "Ini Connolly... dia kembali...",
  ui_story_5066_50661501_11_dialog_content = "Uh... M-maaf membuat semua orang menunggu...!",
  ui_story_5066_50661501_12_dialog_content = "\"Membuat kami menunggu\"? Berhentilah bersikap sopan kepada kami!",
  ui_story_5066_50661501_13_dialog_content = "Melihat bahwa kamu baik-baik saja... adalah kabar terbaik yang bisa kita terima...",
  ui_story_5066_50661501_14_dialog_content = "Jadi, apakah kekuatanmu sudah kembali?",
  ui_story_5066_50661501_15_dialog_content = "Tidak, sepertinya... Dia malah jadi lebih kuat...",
  ui_story_5066_50661501_16_dialog_content = "Sempurna! Mari kita mengepel lantai dengan orang-orang menyebalkan ini dan mengusir mereka, Connolly!",
  ui_story_5066_50661501_17_dialog_content = "B-baik! Saya akan memberikan semuanya!",
  ui_story_5066_50661501_18_dialog_content = "<color=#e8d9bb>Klang—Retak—</color>",
  ui_story_5066_50661501_19_dialog_content = "<color=#e8d9bb>Wuuss, wuuss, wuuss—Plak!</color>",
  ui_story_5066_50661501_20_dialog_content = "Hei, aku pikir kalian seharusnya lebih kuat dari ini!",
  ui_story_5066_50661501_21_dialog_content = "Tidak bisakah satu pun dari kalian bertarung?!",
  ui_story_5066_50661501_22_dialog_content = "<color=#e8d9bb>Klang—Retak—</color>",
  ui_story_5066_50661501_23_dialog_content = "Connolly... Kekuatan yang kamu miliki sekarang... Aku sangat lega...",
  ui_story_5066_50661501_24_dialog_content = "Ya... Dan ini semua karena kalian telah mengulur waktu untukku. Terima kasih banyak...",
  ui_story_5066_50661501_25_dialog_content = "Tak perlu berterima kasih pada kami, terlebih saat masih banyak pertempuran yang harus dihadapi!",
  ui_story_5066_50661501_26_dialog_content = "<color=#e8d9bb>Klang—Retak—</color>",
  ui_story_5066_50661501_27_dialog_content = "...",
  ui_story_5066_50661501_28_dialog_content = "Cukup dengan anak buah kecil! Keluarkan raja congkak kalian sekarang juga!",
  ui_story_5066_50661501_29_dialog_content = "Robyn, pergi bantu Connolly.",
  ui_story_5066_50661501_30_dialog_content = "Roger...",
  ui_story_5066_50661501_31_dialog_content = "Sepertinya inilah kekuatan sejati dari Aqua Queen.",
  ui_story_5066_50661501_32_dialog_content = "Menarik. Memang agak luar biasa.",
  ui_story_5066_50661501_33_dialog_content = "Tapi, apakah kalian benar-benar percaya bahwa aku sedang kalah sekarang?",
  ui_story_5066_50661501_34_dialog_content = "Kamu... Apapun yang sedang kamu rencanakan, aku... aku tidak akan membiarkanmu lolos begitu saja!",
  ui_story_5066_50661501_35_dialog_content = "Hahahaha, menghentikanku? Aku punya semua informasi tentangmu!",
  ui_story_5066_50661501_36_dialog_content = "Jadi, kekuatan Aqua Lord sekarang semuanya berasal dari rumah yang kalian bangun, kastil itu, bukan?",
  ui_story_5066_50661501_37_dialog_content = "Aku akan membawa lebih banyak bola meriam dari perairan dangkal dan meledakkan istana sepenuhnya! Biarkan kekuatan Aqua Lord benar-benar tersebar!",
  ui_story_5066_50661501_38_dialog_content = "Dan kau menyebut dirimu seorang raja, bertarung seperti itu? Kau memalukan, tapi setidaknya kau punya keberanian untuk akhirnya mengatakannya!",
  ui_story_5066_50661501_39_dialog_content = "Heh, kamu punya masalah dengan itu? Apa yang bisa kamu lakukan?",
  ui_story_5066_50661501_40_dialog_content = "Connolly, jika kamu mengakui kesetiaanmu padaku sekarang, mungkin aku akan membiarkan kamu dan monster itu hidup.",
  ui_story_5066_50661501_41_dialog_content = "Buat pilihanmu dengan cepat; aku tidak ingin membuang lebih banyak waktu bersamamu.",
  ui_story_5066_50661501_42_dialog_content = "Aku... Aku berjanji pada Aqua Lord bahwa aku akan melindungi rumahnya... Dan juga rumah semua orang lainnya.",
  ui_story_5066_50661501_43_dialog_content = "Ini adalah tugas saya... Dan saya tidak akan lari darinya lagi!",
  ui_story_5066_50661501_44_dialog_content = "Jika kamu benar-benar bersedia untuk meledakkan kuil itu...",
  ui_story_5066_50661501_45_dialog_content = "Maka dengan wewenangku sebagai Aqua Queen... Untuk membela kota ini, aku menyatakan perang padamu!",
  ui_story_5066_50661501_46_dialog_content = "Bagus, saatnya mengakhiri sandiwara kalian para pemberontak.",
  ui_story_5066_50661501_47_dialog_content = "Semua unit! Atas perintahku! Luncurkan serangan skala penuh ke kota!",
  ui_story_5066_50661501_48_dialog_content = "Jangan biarkan satu pun pemberontak di kota itu lolos!",
  ui_story_5066_50661501_49_dialog_content = "...",
  ui_story_5066_50661501_50_dialog_content = "...",
  ui_story_5066_50661501_51_dialog_content = "...",
  ui_story_5066_50661501_52_dialog_content = "<size=50>Ohhhhhh!</size>",
  ui_story_5066_50661601_1_dialog_content = "*memainkan lagu*",
  ui_story_5066_50661601_2_dialog_content = "<color=#e8d9bb>Plak—Plak!</color>",
  ui_story_5066_50661601_3_dialog_content = "Argh…",
  ui_story_5066_50661601_4_dialog_content = "Argh…",
  ui_story_5066_50661601_5_dialog_content = "...",
  ui_story_5066_50661601_6_dialog_content = "Sepertinya intel dari joker itu salah...",
  ui_story_5066_50661601_7_dialog_content = "Kekuatan berasal dari musik itu sendiri, bukan dari klarinet itu!",
  ui_story_5066_50661601_8_dialog_content = "Tapi dengan cara ini, heh, semuanya jadi terlalu mudah!",
  ui_story_5066_50661601_9_dialog_content = "Bersiap atas perintahku!",
  ui_story_5066_50661601_10_dialog_content = "…!",
  ui_story_5066_50661601_11_dialog_content = "Buat kebisingan sekeras mungkin untuk mengganggu musik Aqua Queen!",
  ui_story_5066_50661601_12_dialog_content = "Ya!",
  ui_story_5066_50661601_13_dialog_content = "Arghhhh! Tutup mulut bodoh kalian, semua!",
  ui_story_5066_50661601_14_dialog_content = "Kita tidak bisa membiarkan orang-orang menyebalkan itu terus membuat keributan! Ayo, Robyn!",
  ui_story_5066_50661601_15_dialog_content = "Mengerti... Kita harus menghentikan mereka...",
  ui_story_5066_50661601_16_dialog_content = "<color=#e8d9bb>Klang—Bam—</color>",
  ui_story_5066_50661601_17_dialog_content = "Lebih keras, buat lebih keras! Biarkan bergema!",
  ui_story_5066_50661601_18_dialog_content = "Urgh... Mereka sangat keras! Saya hampir tidak bisa mendengar suara saya sendiri...",
  ui_story_5066_50661601_19_dialog_content = "Dengan keadaan seperti ini... Jangan bilang itu akan terjadi lagi...",
  ui_story_5066_50661601_20_dialog_content = "Tidak perlu takut, Connolly.",
  ui_story_5066_50661601_21_dialog_content = "Lumba-lumba Putih... Kamu datang untuk membantu saya lagi?",
  ui_story_5066_50661601_22_dialog_content = "Aku... Aku tahu seharusnya aku tidak mudah patah semangat, tapi... Bagaimana aku bisa memainkan laguku sekarang...?",
  ui_story_5066_50661601_23_dialog_content = "Jadilah dirimu sendiri.",
  ui_story_5066_50661601_24_dialog_content = "Hanya... jadi diri sendiri...?",
  ui_story_5066_50661601_25_dialog_content = "Benar. Pertunjukanmu memang bukan untuk pertempuran, bukan?",
  ui_story_5066_50661601_26_dialog_content = "Apa tujuan dari musikmu?",
  ui_story_5066_50661601_27_dialog_content = "Makna musik saya...",
  ui_story_5066_50661601_28_dialog_content = "Namun, aku tidak sepenuhnya merasa tidak bahagia...",
  ui_story_5066_50661601_29_dialog_content = "Dan itu karena... Saya masih punya musik saya! Saya masih memiliki instrumen dan kertas musik yang ditinggalkan mama saya...",
  ui_story_5066_50661601_30_dialog_content = "<color=#e8d9bb>Kapanpun Connolly merasa kesepian, dia memainkan melodi-melodi yang akrab.</color>",
  ui_story_5066_50661601_31_dialog_content = "<color=#e8d9bb>Mars gembira dalam A Major, balada lirik dalam B Minor, dan sonata muram dalam C Major. Lagu-lagu ini bukan hanya teman-temannya, tetapi juga penyelamatnya.</color>",
  ui_story_5066_50661601_32_dialog_content = "A... Aku paham sekarang.",
  ui_story_5066_50661601_33_dialog_content = "Aku selalu sendirian saat memainkan musikku. Itu adalah cara ku menyelamatkan diri...",
  ui_story_5066_50661601_34_dialog_content = "Kebahagiaan tak tergantikan dari memainkan musik milik saya dan tidak ada orang lain... Itu juga yang saya lakukan dengan paling baik...",
  ui_story_5066_50661601_35_dialog_content = "Yang berarti aku masih bisa melakukannya!",
  ui_story_5066_50661601_36_dialog_content = "*memainkan lagu*",
  ui_story_5066_50661601_37_dialog_content = "Bising, di mana bising yang kalian buat?! Kalian harus lebih keras dari musik sialan itu!",
  ui_story_5066_50661601_38_dialog_content = "*memainkan lagu*",
  ui_story_5066_50661601_39_dialog_content = "Uh-oh, Raja Merman tampak sangat asin sekarang!",
  ui_story_5066_50661601_40_dialog_content = "Sekarang saatnya... Untuk membalikkan keadaan pertempuran...",
  ui_story_5066_50661701_1_dialog_content = "<color=#e8d9bb>Bang—Bang—</color>",
  ui_story_5066_50661701_2_dialog_content = "Ayolah, kalian sekumpulan mahluk berwajah ikan! Berikan aku tantangan yang sesungguhnya!",
  ui_story_5066_50661701_3_dialog_content = "Sejak Connolly kembali, pertempuran menjadi lebih mudah... Lega sekali...",
  ui_story_5066_50661701_4_dialog_content = "Pengawal yang tidak berguna ini; sama sekali tidak bisa diandalkan di saat-saat kritis...",
  ui_story_5066_50661701_5_dialog_content = "Tapi kalian pemberontak, jangan terlalu sombong begitu cepat.",
  ui_story_5066_50661701_6_dialog_content = "Sebagai raja, aku tidak berniat untuk bertempur secara langsung.",
  ui_story_5066_50661701_7_dialog_content = "Tapi dengan hal-hal seperti ini sekarang...",
  ui_story_5066_50661701_8_dialog_content = "...!?",
  ui_story_5066_50661701_9_dialog_content = "Yang Mulia, Anda tidak perlu...",
  ui_story_5066_50661701_10_dialog_content = "Diam! Beritahu semua orang untuk menghentikan serangan sia-sia mereka dan alihkan semua kekuatan tembak ke arah kastil!",
  ui_story_5066_50661701_11_dialog_content = "Aku akan menangani pengeboman secara pribadi!",
  ui_story_5066_50661701_12_dialog_content = "Kita akan menghapus kota ini dari peta hari ini, dimulai dengan kastil terkutuk itu!",
  ui_story_5066_50661701_13_dialog_content = "Tapi dengan cara ini, meskipun kita menang dalam pertempuran ini, kita tidak akan mendapatkan apa-apa...",
  ui_story_5066_50661701_14_dialog_content = "Diam, kalian sekelompok yang tidak berguna! Cukup ikuti perintahku!",
  ui_story_5066_50661701_15_dialog_content = "Ya!!!",
  ui_story_5066_50661701_16_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5066_50661701_17_dialog_content = "Ledakan meriam itu tampak lebih kuat dari sebelumnya!",
  ui_story_5066_50661701_18_dialog_content = "Apakah dia... mencoba meratakan seluruh kota...?",
  ui_story_5066_50661701_19_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5066_50661701_20_dialog_content = "Dan sepertinya mereka sedang fokus menyerang kuil itu sendiri!",
  ui_story_5066_50661701_21_dialog_content = "Dengan keadaan seperti ini... Kuil ini akan segera menjadi puing-puing...",
  ui_story_5066_50661701_22_dialog_content = "Tidak... Aku tidak bisa membiarkan dia menghancurkan candi itu!",
  ui_story_5066_50661701_23_dialog_content = "Ini adalah... Rumah Aqua Lord... Dan semua orang bekerja keras untuk membangunnya!",
  ui_story_5066_50661701_24_dialog_content = "Kita tidak bisa... Kami tidak akan membiarkan Raja Merman meruntuhkannya!",
  ui_story_5066_50661701_25_dialog_content = "<color=#e8d9bb>Wuush—Wuush—Wuush—</color>",
  ui_story_5066_50661701_26_dialog_content = "<color=#e8d9bb>Dengan segenap kekuatannya, Connolly berhasil menghalau setiap tembakan meriam yang datang dengan tentakelnya.</color>",
  ui_story_5066_50661701_27_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5066_50661701_28_dialog_content = "Connolly!!!",
  ui_story_5066_50661701_29_dialog_content = "Kamu bakal terluka kalau terus begini!",
  ui_story_5066_50661701_30_dialog_content = "Tapi kuilnya... Aku tak bisa membiarkannya...",
  ui_story_5066_50661701_31_dialog_content = "...",
  ui_story_5066_50661701_32_dialog_content = "Tak apa-apa, Connolly, semuanya baik-baik saja.",
  ui_story_5066_50661701_33_dialog_content = "Hah... Apakah itu kamu, Aqua Lord...?",
  ui_story_5066_50661701_34_dialog_content = "Tekad dan emosimu sangat jelas bagiku.",
  ui_story_5066_50661701_35_dialog_content = "Aku akan melindungi kota ini. Jadi kamu bisa berusaha keras melawan Raja Merman.",
  ui_story_5066_50661701_36_dialog_content = "Namun…",
  ui_story_5066_50661701_37_dialog_content = "Tidak ada \"tapi.\" Connolly, sudah kubilang padamu bahwa menjadi ratu sejati datang dengan lebih banyak tanggung jawab...",
  ui_story_5066_50661701_38_dialog_content = "Tapi perjanjian kita... Dan rumahmu...",
  ui_story_5066_50661701_39_dialog_content = "Rumah... Ahahahahahah...",
  ui_story_5066_50661701_40_dialog_content = "Kali ini, kamu yang tidak mengerti.",
  ui_story_5066_50661701_41_dialog_content = "Aku...?",
  ui_story_5066_50661701_42_dialog_content = "Kamu sudah lama memberitahuku melalui lagu-lagumu tentang arti sebenarnya dari rumah. Apakah kamu tidak ingat?",
  ui_story_5066_50661701_43_dialog_content = "Kota ini adalah rumah bagi semua penghuni bawah air, dan para penduduk kota serta kamu bersama yang membangun rumah baru untukku...",
  ui_story_5066_50661701_44_dialog_content = "Selama kota ini masih ada, rumah yang saya inginkan selalu bisa dibangun kembali, cepat atau lambat.",
  ui_story_5066_50661701_45_dialog_content = "Aqua Lord...",
  ui_story_5066_50661701_46_dialog_content = "Pergilah sekarang. Kali ini, biarkan aku bergabung denganmu... untuk melindungi kota tercinta kita, rumah yang paling kita hargai... rumah!",
  ui_story_5066_50661702_1_dialog_content = "<color=#e8d9bb>Whoosh—Smack—</color>",
  ui_story_5066_50661702_2_dialog_content = "Aduhhh...",
  ui_story_5066_50661702_3_dialog_content = "<color=#e8d9bb>Wuuss—Tepis—</color>",
  ui_story_5066_50661702_4_dialog_content = "Haa... Haa... Akhirnya selesai juga...",
  ui_story_5066_50661702_5_dialog_content = "Sial...",
  ui_story_5066_50661702_6_dialog_content = "Aku... Raja Merman yang perkasa... tidak percaya aku... kalah dengan seseorang sepertimu...",
  ui_story_5066_50661702_7_dialog_content = "Heheheheh... Tidak, aku belum kalah! Ini belum berakhir!",
  ui_story_5066_50661702_8_dialog_content = "Connolly, dengarkan!",
  ui_story_5066_50661702_9_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5066_50661702_10_dialog_content = "Bombardment belum berakhir, tetapi kamu tidak memiliki kekuatan untuk menghentikannya lagi!",
  ui_story_5066_50661702_11_dialog_content = "Kemenangan akan jadi milikku! MILIKKU!",
  ui_story_5066_50661702_12_dialog_content = "Hahahaha... Hidup Kerajaan Merman!",
  ui_story_5066_50661702_13_dialog_content = "Kota ini... semuanya...",
  ui_story_5066_50661702_14_dialog_content = "Aku... Aku mungkin benar-benar lelah sekarang, tapi... Aku tidak sendirian dalam pertarungan ini!",
  ui_story_5066_50661702_15_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5066_50661702_16_dialog_content = "Aaahhhh—",
  ui_story_5066_50661702_17_dialog_content = "Tidak peduli sekeras apa omongan besar Anda, itu tidak akan menutupi suara meriam!",
  ui_story_5066_50661702_18_dialog_content = "Aku pemenangnya! Ini kemenanganku!",
  ui_story_5066_50661702_19_dialog_content = "<color=#e8d9bb>Di bawah hujan tembakan meriam, tubuh Connolly terombang-ambing tak berdaya seperti rumput laut.</color>",
  ui_story_5066_50661702_20_dialog_content = "<color=#e8d9bb>Melihat ke atas, dia melihat sesuatu mengapung jauh di permukaan air. Sebuah cahaya hangat dan familiar...</color>",
  ui_story_5066_50661702_21_dialog_content = "Aqua Lord...",
  ui_story_5066_50661702_22_dialog_content = "Aku... aku berhasil mengalahkan Raja Merman, seperti yang aku katakan... Aku telah menunaikan tugas-tugasku!",
  ui_story_5066_50661702_23_dialog_content = "Tapi tubuhmu... Apa yang terjadi padanya?!",
  ui_story_5066_50661702_24_dialog_content = "Anda telah melakukannya dengan baik...",
  ui_story_5066_50661702_25_dialog_content = "Namun, untuk melindungi kota... kamu akan memerlukan kekuatan yang lebih canggih, kekuatan sejati Aqua Queen...",
  ui_story_5066_50661702_26_dialog_content = "Sekarang... aku meneruskan kekuatan ini kepadamu.",
  ui_story_5066_50661702_27_dialog_content = "Tidak... Tunggu, Aqua Lord! Ini bukan yang kita sepakati...!",
  ui_story_5066_50661702_28_dialog_content = "Bukankah kita... Bukankah kita seharusnya mempertahankan kota ini bersama-sama?!",
  ui_story_5066_50661702_29_dialog_content = "Memang, kamu... akan mewarisi seluruh kekuatan yang kupunya...",
  ui_story_5066_50661702_30_dialog_content = "Dan aku akan selalu bersamamu, menjaga kota ini...",
  ui_story_5066_50661702_31_dialog_content = "Menjaga... rumah kita.",
  ui_story_5066_50661702_32_dialog_content = "Tunggu, Aqua Lord... tolong jangan menghilang... jangan tinggalkan aku sendiri...",
  ui_story_5066_50661702_33_dialog_content = "Selamanya, kamu... tidak akan sendirian...",
  ui_story_5066_50661702_34_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_5066_50661702_35_dialog_content = "Air... Lord...",
  ui_story_5066_50661702_36_dialog_content = "Kekuatan ini... rasanya sangat hangat...",
  ui_story_5066_50661702_37_dialog_content = "Ini adalah... Kekuatan penuh dari Aqua Lord... yang ia berikan kepadaku...",
  ui_story_5066_50661702_38_dialog_content = "Tapi sekarang bukan saatnya untuk berkabung...!",
  ui_story_5066_50661702_39_dialog_content = "Kehendak dan keinginan Sang Penguasa Aqua... Kini menjadi milikku!",
  ui_story_5066_50661702_40_dialog_content = "Hmph... tidak ada apa-apa selain gertakan!",
  ui_story_5066_50661702_41_dialog_content = "Sebenarnya, monster itu tidak bisa menahan serangan bombardirku... dan menghilang. Bukankah itu jelas?",
  ui_story_5066_50661702_42_dialog_content = "Meriam ini tidak akan berhenti menembak, dan kamu...",
  ui_story_5066_50661702_43_dialog_content = "<color=#e8d9bb>Connolly tidak bicara, melainkan dengan lembut mengangkat klarinetnya.</color>",
  ui_story_5066_50661702_44_dialog_content = "Kamu... sudah sampai di titik ini, apa lagi yang bisa kamu lakukan?!",
  ui_story_5066_50661702_45_dialog_content = "Ninabobo ini didedikasikan untuk kamu, serta para prajurit kejam dan tak berhati nurani yang lain.",
  ui_story_5066_50661702_46_dialog_content = "Mimpimu untuk menghancurkan kota ini telah berakhir. Sekarang saatnya... untukku mengantarkanmu ke mimpi yang baru.",
  ui_story_5066_50661702_47_dialog_content = "Silakan nikmati saat kami kembali mengantarkan Anda ke perairan dangkal!",
  ui_story_5066_50661702_48_dialog_content = "*memainkan lagu*",
  ui_story_5066_50661702_49_dialog_content = "<color=#e8d9bb>Connolly memainkan sebuah lagu yang lembut dan mengharukan, yang penuh dengan kekuatan persahabatan, kenangan, dan tekadnya yang kuat.</color>",
  ui_story_5066_50661702_50_dialog_content = "<color=#e8d9bb>Setiap musuh, termasuk Raja Merman, terlelap dalam tidur yang dalam saat Connolly memberikan penampilan yang sempurna...</color>",
  ui_story_5066_50661702_51_dialog_content = "Tidak bisa percaya. Hanya satu lagu saja yang dibutuhkan untuk mengubah para putri duyung haus darah itu menjadi sekolah ikan yang mengantuk!",
  ui_story_5066_50661702_52_dialog_content = "Bangun, nafas-umpan! Kita belum selesai bertarung!",
  ui_story_5066_50661702_53_dialog_content = "Jadi ini adalah kekuatan Connolly... Tapi sepertinya ada sesuatu yang buruk terjadi juga...",
  ui_story_5066_50661702_54_dialog_content = "Ya aku tahu.",
  ui_story_5066_50661702_55_dialog_content = "Aqua Lord sudah pergi sekarang, kan?",
  ui_story_5066_50661702_56_dialog_content = "Makanya kita seharusnya menghiburnya sekarang daripada hanya berdiri di sini...",
  ui_story_5066_50661702_57_dialog_content = "Mengerti! Ayo bergerak!",
  ui_story_5066_50661702_58_dialog_content = "Apakah... Apakah kali ini benar-benar sudah selesai?",
  ui_story_5066_50661702_59_dialog_content = "Kerja yang fantastis, Connolly.",
  ui_story_5066_50661702_60_dialog_content = "T-Tolong jangan memujiku. Seharusnya aku berterima kasih padamu karena telah membimbingku selama ini...",
  ui_story_5066_50661702_61_dialog_content = "Hanya sedikit bantuan dari saya. Saya harus bilang, penampilan Anda saat menyanyikan lagu pengantar tidur tadi sangat menawan dan anggun.",
  ui_story_5066_50661702_62_dialog_content = "Aaahhhh... K-Kamu mengolok-olokku, ya?!",
  ui_story_5066_50661702_63_dialog_content = "Oke, teman-temanmu datang tepat waktu; mari kita rayakan kemenangan ini bersama-sama!",
  ui_story_5066_50661702_64_dialog_content = "Hai, Connolly! Di sini!",
  ui_story_5066_50661702_65_dialog_content = "Lihat, kami mengumpulkan semua putri duyung yang tidur di satu tempat!",
  ui_story_5066_50661702_66_dialog_content = "Mereka benar-benar licin... Ini jauh lebih banyak pekerjaan daripada yang kukira...",
  ui_story_5066_50661702_67_dialog_content = "Kepala Raja Merman cukup besar, sih. Menurutmu, kita bisa memaksakannya masuk ke sana?",
  ui_story_5066_50661702_68_dialog_content = "Saya rasa... Dia akan cocok dengan baik!",
  ui_story_5066_50661702_69_dialog_content = "Baiklah, ini dia!",
  ui_story_5066_50661702_70_dialog_content = "Menyerang kota yang tak berdaya dengan meriam dan bahan peledak... Aku yakin bahkan seorang tiran seperti dia tak pernah terpikirkan...",
  ui_story_5066_50661702_71_dialog_content = "Jadi dia juga akan ditembak keluar dari meriam suatu hari nanti, ya?",
  ui_story_5066_50661702_72_dialog_content = "Sejujurnya, aku sangat penasaran bagaimana hasilnya nanti...",
  ui_story_5066_50661702_73_dialog_content = "Saya... Saya hanya merasa ini adalah cara terbaik untuk mengeluarkan mereka semua dari sini...",
  ui_story_5066_50661702_74_dialog_content = "Kota kecil ini akhirnya akan mengenal kedamaian dan keamanan setelah ini...",
  ui_story_5066_50661702_75_dialog_content = "Bisakah kamu menyalakan sumbunya sekarang, Connolly? Aku sangat ingin melihat benda ini meledak!",
  ui_story_5066_50661702_76_dialog_content = "Oke, tentu saja...",
  ui_story_5066_50661702_77_dialog_content = "Tiga, dua, satu—Api!",
  ui_story_5066_50661702_78_dialog_content = "<size=45><color=#e8d9bb>Duar—!</color></size>",
  ui_story_5066_50661702_79_dialog_content = "Um... Apakah ini cara semuanya harus berakhir, Lumba-Lumba Putih...?",
  ui_story_5066_50661702_80_dialog_content = "Tentu saja. Tidak ada akhir yang lebih baik dari ini.",
  ui_story_5066_50661702_81_dialog_content = "Untuk kalian semua, putra duyung yang jelek, semoga kalian menikmati mimpi di dalam mimpi ini.",
  ui_story_5066_50661801_1_dialog_content = "Fiuh... Akhirnya semua selesai...",
  ui_story_5066_50661801_2_dialog_content = "Semua ini terasa seperti mimpi aneh...",
  ui_story_5066_50661801_3_dialog_content = "Mungkin... Jika aku bisa tertidur seperti ikan-ikan lainnya...",
  ui_story_5066_50661801_4_dialog_content = "Bisakah aku... Melihat Aqua Lord sekali lagi?",
  ui_story_5066_50661801_5_dialog_content = "Hey Connolly, orang-orang ini mengatakan bahwa rumah mereka hancur dalam pertempuran. Bukankah kita harus mencari cara untuk melindungi mereka untuk sementara waktu?",
  ui_story_5066_50661801_6_dialog_content = "Dan anak ini mengatakan bahwa dia terpisah dari ibunya... Tapi jangan khawatir, saya akan membantu mencarinya...",
  ui_story_5066_50661801_7_dialog_content = "Ahh, maaf ya...",
  ui_story_5066_50661801_8_dialog_content = "Sekarang bukan saatnya untuk berkubang dalam kesedihanku...",
  ui_story_5066_50661801_9_dialog_content = "Aku berjanji bahwa aku akan menjadi Aqua Queen yang sejati... Dan aku menolak untuk lari dari tugas-tugas ku lagi...",
  ui_story_5066_50661801_10_dialog_content = "Dayna! Robyn! Aku akan segera ke sana...",
  ui_story_5066_50661801_11_dialog_content = "<color=#e8d9bb>Wiss—Wiss—Wiss—</color>",
  ui_story_5066_50661801_12_dialog_content = "Hah?!",
  ui_story_5066_50661801_13_dialog_content = "Apakah ini... tentakel air? Tapi mereka sangat kecil...",
  ui_story_5066_50661801_14_dialog_content = "Aqua Lord... Kamu masih di sini?! Kamu tidak pernah meninggalkanku, ya...?",
  ui_story_5066_50661801_15_dialog_content = "Aqua Lord? Tapi... bukankah kamu Aqua Lord yang sebenarnya?!",
  ui_story_5066_50661801_16_dialog_content = "Hah...? A-Aku?!",
  ui_story_5066_50661801_17_dialog_content = "Benar, kami adalah pelayan Anda... dan juga teman Anda...",
  ui_story_5066_50661801_18_dialog_content = "Kami datang untuk bersamamu agar kamu tidak kesepian!",
  ui_story_5066_50661801_19_dialog_content = "Menemaniku...?",
  ui_story_5066_50661801_20_dialog_content = "Memang, kamu... akan mewarisi seluruh kekuatan yang kupunya...",
  ui_story_5066_50661801_21_dialog_content = "Dan aku akan selalu bersamamu, menjaga kota ini...",
  ui_story_5066_50661801_22_dialog_content = "Menjaga... rumah kita.",
  ui_story_5066_50661801_23_dialog_content = "Selamanya, kamu... tidak akan sendirian...",
  ui_story_5066_50661801_24_dialog_content = "(Jadi ini berarti... Aqua Lord tidak benar-benar menghilang...)",
  ui_story_5066_50661801_25_dialog_content = "(Sebaliknya, itu kembali... Sebagai tiga entitas yang berbeda!)",
  ui_story_5066_50661801_26_dialog_content = "Uh... Dari mana tepatnya... Kalian bertiga berasal...?",
  ui_story_5066_50661801_27_dialog_content = "Kami datang dari dimensi lain!",
  ui_story_5066_50661801_28_dialog_content = "Dimensi ilusi!",
  ui_story_5066_50661801_29_dialog_content = "Dimensi imajinasi!",
  ui_story_5066_50661801_30_dialog_content = "Dimensi musik!",
  ui_story_5066_50661801_31_dialog_content = "Dan ada... Tiga dari kalian?",
  ui_story_5066_50661801_32_dialog_content = "Saat kamu berbicara, terdengar seperti mars, balada, dan sonata yang dimainkan secara bersamaan.",
  ui_story_5066_50661801_33_dialog_content = "Maaf, aku sedikit kesulitan membedakan kalian bertiga...",
  ui_story_5066_50661801_34_dialog_content = "Aku memainkan mars! Nada yang paling kuat!",
  ui_story_5066_50661801_35_dialog_content = "Aku memainkan balada, lagu-lagu lembut dalam tangga nada minor.",
  ui_story_5066_50661801_36_dialog_content = "Aku memainkan sonata, sederhana namun mendalam, dalam kunci mayor yang lebih dalam dan luas.",
  ui_story_5066_50661801_37_dialog_content = "Wahai Aqua Queen yang perkasa, bisakah kamu membedakan kami sekarang?",
  ui_story_5066_50661801_38_dialog_content = "Sekarang aku bisa membedakan kalian dengan sempurna! Kalian masing-masing memiliki suara yang sangat indah juga!",
  ui_story_5066_50661801_39_dialog_content = "Tapi tetap saja, mengapa kamu terlahir kembali sebagai tiga makhluk yang berbeda...?",
  ui_story_5066_50661801_40_dialog_content = "Memang canggung bagi Bangsawan Aqua Lord untuk mengakuinya, tetapi ia hanya memiliki satu pengiring! Memiliki tiga pengiring justru menambah keagungan!",
  ui_story_5066_50661801_41_dialog_content = "Dengan hanya satu teman, mungkin terkadang kau merasa kesepian, tetapi dengan tiga, hal itu tidak akan terjadi.",
  ui_story_5066_50661801_42_dialog_content = "Memiliki satu teman bukanlah cukup untuk keluarga yang kokoh, tetapi tiga orang cukup untuk mengatasi kesulitan.",
  ui_story_5066_50661801_43_dialog_content = "Connolly! Mulai hari ini, biarlah kami yang menemani Anda!"
}
return config
